    warn.port_release_hint) echo "If this is not the application you are deploying, free the port first or the service will fail to bind.|若非你要部署的应用，请先释放端口，否则服务将无法绑定。" ;;
    *) echo "$key|$key" ;;
  esac
}

t() {
  local key="$1"
  shift || true
  local pair text
  if [[ "$DEPLOY_LANG" == "zh" && -v "__DEPLOY_I18N_ZH[$key]" ]]; then
    i18n_print "${__DEPLOY_I18N_ZH[$key]}" "$@"
    return 0
  fi
  if [[ -v "__DEPLOY_I18N_EN[$key]" ]]; then
    i18n_print "${__DEPLOY_I18N_EN[$key]}" "$@"
    return 0
  fi
  pair="$(__deploy_i18n_message "$key")"
  if [[ "$DEPLOY_LANG" == "zh" ]]; then
    text="${pair#*|}"
  else
    text="${pair%%|*}"
  fi
  i18n_print "$text" "$@"
}

# ----- lib/logging.sh -----

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
BOLD='\033[1m'
NC='\033[0m'

info() { echo -e "${BLUE}[i]${NC} $*" >&2; }
success() { echo -e "${GREEN}[+]${NC} $*" >&2; }
warn() { echo -e "${YELLOW}[!]${NC} $*" >&2; }
error() { echo -e "${RED}[x]${NC} $*" >&2; exit 1; }
step() { echo -e "\n${CYAN}${BOLD}== $* ==${NC}" >&2; }
prompt() { echo -ne "${YELLOW}[?]${NC} $* " >&2; }

# ----- lib/fs.sh -----

require_root() {
  local action="${1:-}"
  [[ ${EUID:-$(id -u)} -eq 0 ]] || error "$(t error.root_required "$0" "$action")"
}

require_command() {
  local command_name="$1"
  command -v "$command_name" >/dev/null 2>&1 || error "$(t error.command_required "$command_name")"
}

is_safe_path() {
  local path="${1:-}"
  [[ -n "$path" ]] || return 1
  [[ "$path" = /* ]] || return 1

  while [[ "$path" != "/" && "$path" == */ ]]; do
    path="${path%/}"
  done

  case "$path" in
    /|.|..|*'/../'*|*'/..'|*'/./'*|*'/.')
      return 1
      ;;
    /bin|/boot|/dev|/etc|/home|/lib|/lib64|/opt|/proc|/root|/run|/sbin|/sys|/tmp|/usr|/var|/var/lib|/var/log|/usr/local|/usr/local/bin)
      return 1
      ;;
  esac
  return 0
}

require_safe_path() {
  local name="$1"
  local path="$2"
  is_safe_path "$path" || error "$(t error.unsafe_path "$name" "${path:-empty}")"
}

safe_rm_dir() {
  local path="$1"
  local name="${2:-path}"
  while [[ "$path" != "/" && "$path" == */ ]]; do
    path="${path%/}"
  done
  require_safe_path "$name" "$path"
  [[ -e "$path" || -L "$path" ]] || return 0
  [[ -d "$path" || -L "$path" ]] || return 1
  rm -rf -- "$path"
}

# ----- lib/atomic.sh -----

atomic_write_file() {
  local target_path="$1"
  local mode="${2:-}"
  local owner="${3:-}"
  local target_dir target_tmp
  target_dir="$(dirname "$target_path")"
  if ! mkdir -p "$target_dir"; then
    return 1
  fi
  if ! target_tmp="$(mktemp "${target_dir}/.$(basename "$target_path").XXXXXX")"; then
    return 1
  fi
  if ! cat > "$target_tmp"; then
    rm -f "$target_tmp"
    return 1
  fi
  if [[ -n "$mode" ]] && ! chmod "$mode" "$target_tmp"; then
    rm -f "$target_tmp"
    return 1
  fi
  if [[ -n "$owner" ]] && ! chown "$owner" "$target_tmp" 2>/dev/null; then
    rm -f "$target_tmp"
    return 1
  fi
  if ! mv "$target_tmp" "$target_path"; then
    rm -f "$target_tmp"
    return 1
  fi
}

atomic_copy_file() {
  local source_path="$1"
  local target_path="$2"
  local mode="${3:-}"
  local owner="${4:-}"
  local target_dir target_tmp
  [[ -f "$source_path" ]] || return 1
  target_dir="$(dirname "$target_path")"
  if ! mkdir -p "$target_dir"; then
    return 1
  fi
  if ! target_tmp="$(mktemp "${target_path}.XXXXXX")"; then
    return 1
  fi
  if ! cp "$source_path" "$target_tmp"; then
    rm -f "$target_tmp"
    return 1
  fi
  if [[ -n "$mode" ]] && ! chmod "$mode" "$target_tmp"; then
    rm -f "$target_tmp"
    return 1
  fi
  if [[ -n "$owner" ]] && ! chown "$owner" "$target_tmp" 2>/dev/null; then
    rm -f "$target_tmp"
    return 1
  fi
  if ! mv "$target_tmp" "$target_path"; then
    rm -f "$target_tmp"
    return 1
  fi
}

atomic_symlink() {
  local target_path="$1"
  local link_path="$2"
  local link_dir link_tmp
  link_dir="$(dirname "$link_path")"
  if ! mkdir -p "$link_dir"; then
    return 1
  fi
  if ! link_tmp="$(mktemp "${link_path}.XXXXXX")"; then
    return 1
  fi
  rm -f "$link_tmp"
  if ! ln -s "$target_path" "$link_tmp" || ! mv -Tf "$link_tmp" "$link_path"; then
    rm -f "$link_tmp"
    return 1
  fi
}

# ----- lib/binary.sh -----

app_binary_restore_moved_backup() {
  local backup_path="$1"
  local restore_tmp
  [[ -n "$backup_path" && -f "$backup_path" ]] || return 0
  [[ ! -e "$BIN_PATH" ]] || return 1
  if ! restore_tmp="$(mktemp "${BIN_PATH}.restore.XXXXXX")"; then
    return 1
  fi
  if ! cp "$backup_path" "$restore_tmp"; then
    rm -f "$restore_tmp"
    return 1
  fi
  if ! chmod +x "$restore_tmp" \
      || ! chown "${SERVICE_USER}:${SERVICE_USER}" "$restore_tmp" \
      || ! mv "$restore_tmp" "$BIN_PATH"; then
    rm -f "$restore_tmp"
    return 1
  fi
  rm -f "$backup_path"
}

app_binary_install_candidate() {
  local tmp_bin="$1"
  local backup_path="${2:-}"
  if [[ -n "$backup_path" && -f "$BIN_PATH" ]]; then
    if ! mv "$BIN_PATH" "$backup_path"; then
      rm -f "$tmp_bin"
      return 1
    fi
  fi
  if ! mv "$tmp_bin" "$BIN_PATH"; then
    rm -f "$tmp_bin"
    app_binary_restore_moved_backup "$backup_path" || return 1
    return 1
  fi
  if ! chmod +x "$BIN_PATH" || ! chown "${SERVICE_USER}:${SERVICE_USER}" "$BIN_PATH"; then
    rm -f "$BIN_PATH"
    app_binary_restore_moved_backup "$backup_path" || return 1
    return 1
  fi
}

app_binary_restore_backup() {
  local backup_path="$1"
  local restore_tmp
  [[ -f "$backup_path" ]] || return 1
  if ! restore_tmp="$(mktemp "${BIN_PATH}.restore.XXXXXX")"; then
    return 1
  fi
  if ! cp "$backup_path" "$restore_tmp"; then
    rm -f "$restore_tmp"
    return 1
  fi
  if ! chmod +x "$restore_tmp" \
      || ! chown "${SERVICE_USER}:${SERVICE_USER}" "$restore_tmp" \
      || ! mv "$restore_tmp" "$BIN_PATH"; then
    rm -f "$restore_tmp"
