deploy_app_file_for() {
  case "$1" in
    newapi) echo "apps/newapi.sh" ;;
    sub2api) echo "apps/sub2api.sh" ;;
    vaultwarden) echo "apps/vaultwarden.sh" ;;
    cyberstrikeai) echo "apps/cyberstrikeai.sh" ;;
    blog) echo "apps/blog.sh" ;;
    tickflow) echo "apps/tickflow.sh" ;;
    *) return 1 ;;
  esac
}

deploy_app_impl_file_for() {
  case "$1" in
    newapi) echo "impl/install_newapi.sh" ;;
    sub2api) echo "impl/install_sub2api.sh" ;;
    vaultwarden) echo "impl/install_vaultwarden.sh" ;;
    cyberstrikeai) echo "impl/install_cyberstrikeai.sh" ;;
    blog) echo "impl/install_blog.sh" ;;
    tickflow) echo "impl/install_tickflow.sh" ;;
    *) return 1 ;;
  esac
}

deploy_app_name_for() {
  case "$1" in
    newapi) echo "New API" ;;
    sub2api) echo "Sub2API" ;;
    vaultwarden) echo "Vaultwarden" ;;
    cyberstrikeai) echo "CyberStrikeAI" ;;
    blog) echo "Hugo Blog" ;;
    tickflow) echo "TickFlow Stock Panel" ;;
    *) return 1 ;;
  esac
}

deploy_app_index_for() {
  local app_id="$1" index=1 id
  for id in "${DEPLOY_APP_IDS[@]}"; do
    if [[ "$id" == "$app_id" ]]; then
      echo "$index"
      return 0
    fi
    index=$((index + 1))
  done
  return 1
}

deploy_app_id_from_selection() {
  local selection index=1 id
  selection="$(deploy_trim "${1:-}")"
  case "${selection,,}" in
    q|quit|exit) return 2 ;;
  esac
  for id in "${DEPLOY_APP_IDS[@]}"; do
    if [[ "${selection,,}" == "$id" || "$selection" == "$index" ]]; then
      echo "$id"
      return 0
    fi
    index=$((index + 1))
  done
  return 1
}

# ----- lib/app_loader.sh -----

ensure_bundled_impl_dir() {
  [[ "${DEPLOY_BUNDLED:-0}" == "1" ]] || return 0
  [[ -n "${DEPLOY_BUNDLED_IMPL_DIR:-}" ]] && return 0

  local tmp_root
  tmp_root="${TMPDIR:-/tmp}"
  tmp_root="${tmp_root%/}"
  DEPLOY_BUNDLED_IMPL_DIR="$(mktemp -d "${tmp_root}/deploy-scripts.${APP_ID:-app}.XXXXXX")" \
    || error "Failed to create bundled implementation directory"
  if ! chmod 700 "$DEPLOY_BUNDLED_IMPL_DIR"; then
    safe_rm_dir "$DEPLOY_BUNDLED_IMPL_DIR" "bundled implementation directory"
    unset DEPLOY_BUNDLED_IMPL_DIR
    error "Failed to secure bundled implementation directory"
  fi
}

app_impl_script_path() {
  local script="${APP_IMPL_SCRIPT:-}"
  if [[ "${DEPLOY_BUNDLED:-0}" == "1" ]]; then
    ensure_bundled_impl_dir
    echo "${DEPLOY_BUNDLED_IMPL_DIR}/${BUNDLED_APP_IMPL_SCRIPT_NAME}"
    return 0
  fi
  [[ -n "$script" ]] || error "APP_IMPL_SCRIPT is not configured for ${APP_ID:-unknown}"
  if [[ "$script" = /* ]]; then
    echo "$script"
  else
    echo "${DEPLOY_ROOT_DIR}/${script}"
  fi
}

ensure_bundled_app_impl_script() {
  [[ "${DEPLOY_BUNDLED:-0}" == "1" ]] || return 0
  local script_path tmp_path
  ensure_bundled_impl_dir
  script_path="$(app_impl_script_path)"
  tmp_path="$(mktemp "${script_path}.XXXXXX")" \
    || error "Failed to create bundled app implementation payload"
  local marker
  marker="__DEPLOY_APP_IMPL_SCRIPT__ ${BUNDLED_APP_IMPL_SCRIPT_NAME:-}"
  if grep -qxF "$marker" "${BASH_SOURCE[0]}"; then
    if ! awk -v marker="$marker" '
        $0 == marker { found=1; next }
        found && $0 == "__DEPLOY_APP_IMPL_SCRIPT_END__" { exit }
        found { print }
      ' "${BASH_SOURCE[0]}" > "$tmp_path"; then
      rm -f "$tmp_path"
      cleanup_bundled_app_impl_script
      error "Failed to extract bundled implementation payload"
    fi
  elif ! awk "/^__DEPLOY_APP_IMPL_SCRIPT__$/ { found=1; next } found { print }" "${BASH_SOURCE[0]}" > "$tmp_path"; then
    rm -f "$tmp_path"
    cleanup_bundled_app_impl_script
    error "Failed to extract bundled app implementation payload"
  fi
  if [[ ! -s "$tmp_path" ]]; then
    rm -f "$tmp_path"
    cleanup_bundled_app_impl_script
    error "Bundled app implementation payload is empty"
  fi
  if ! chmod 700 "$tmp_path"; then
    rm -f "$tmp_path"
    cleanup_bundled_app_impl_script
    error "Failed to secure bundled app implementation payload"
  fi
  if ! mv "$tmp_path" "$script_path"; then
    rm -f "$tmp_path"
    cleanup_bundled_app_impl_script
    error "Failed to install bundled app implementation payload"
  fi
}

cleanup_bundled_app_impl_script() {
  [[ "${DEPLOY_BUNDLED:-0}" == "1" ]] || return 0
  [[ -n "${DEPLOY_BUNDLED_IMPL_DIR:-}" ]] || return 0
  safe_rm_dir "$DEPLOY_BUNDLED_IMPL_DIR" "bundled implementation directory"
  unset DEPLOY_BUNDLED_IMPL_DIR
}

restore_framework_functions() {
  info() { echo -e "${BLUE}[i]${NC} $*" >&2; }
  success() { echo -e "${GREEN}[+]${NC} $*" >&2; }
  warn() { echo -e "${YELLOW}[!]${NC} $*" >&2; }
  error() { echo -e "${RED}[x]${NC} $*" >&2; exit 1; }
  step() { echo -e "\n${CYAN}${BOLD}== $* ==${NC}" >&2; }
  prompt() { echo -ne "${YELLOW}[?]${NC} $* " >&2; }

  show_banner() {
    echo -e "\n${BOLD}${CYAN}${APP_NAME:-Deployment Manager}${NC}"
    [[ -n "${APP_DESCRIPTION:-}" ]] && echo -e "${APP_DESCRIPTION}\n"
  }

  usage() {
    echo "$(t common.usage "$0")" >&2
    echo "      $(t common.no_argument_menu)" >&2
  }

  show_menu() {
    show_banner
    echo "$(t common.choose_action)"
    echo
    echo "  1) install    - $(t menu.install_desc)"
    echo "  2) update     - $(t menu.update_desc)"
    echo "  3) backup     - $(t menu.backup_desc)"
    echo "  4) status     - $(t menu.status_desc)"
    echo "  5) uninstall  - $(t menu.uninstall_desc)"
    echo "  q) $(t common.quit)"
    echo
    prompt "$(t common.selection_prompt)"
    local choice
    read -r choice
    dispatch_action "$choice"
  }

  dispatch_action() {
    local action="${1:-menu}"
    if declare -f deploy_trim >/dev/null 2>&1; then
      action="$(deploy_trim "$action")"
    fi
    case "${action,,}" in
      install|1) do_install ;;
      update|2) do_update ;;
      backup|3) do_backup ;;
      status|4) do_status ;;
      uninstall|5) do_uninstall ;;
      menu|"") show_menu ;;
      q|quit|exit) exit 0 ;;
      *) error "$(t common.invalid_choice "$action")" ;;
    esac
  }
}

load_app_impl() {
  APP_IMPL_SCRIPT="$1"
  ensure_bundled_impl_dir
  ensure_bundled_app_impl_script
  local script_path
  script_path="$(app_impl_script_path)"
  [[ -f "$script_path" ]] || error "App implementation script not found: $script_path"
  if DEPLOY_IMPL_SOURCE_ONLY=1 source "$script_path"; then
    unset DEPLOY_IMPL_SOURCE_ONLY
    cleanup_bundled_app_impl_script
  else
    local source_status=$?
    unset DEPLOY_IMPL_SOURCE_ONLY
    cleanup_bundled_app_impl_script
    return "$source_status"
  fi
  restore_framework_functions
}

# ----- lib/cli.sh -----

show_banner() {
  echo -e "\n${BOLD}${CYAN}${APP_NAME:-Deployment Manager}${NC}"
  [[ -n "${APP_DESCRIPTION:-}" ]] && echo -e "${APP_DESCRIPTION}\n"
}

usage() {
  echo "$(t common.usage "$0")" >&2
  echo "      $(t common.no_argument_menu)" >&2
}

show_menu() {
  show_banner
  echo "$(t common.choose_action)"
  echo
  echo "  1) install    - $(t menu.install_desc)"
  echo "  2) update     - $(t menu.update_desc)"
  echo "  3) backup     - $(t menu.backup_desc)"
  echo "  4) status     - $(t menu.status_desc)"
  echo "  5) uninstall  - $(t menu.uninstall_desc)"
  echo "  q) $(t common.quit)"
  echo
  prompt "$(t common.selection_prompt)"
  local choice
  read -r choice
  dispatch_action "$choice"
}

dispatch_action() {
  local action="${1:-menu}"
  if declare -f deploy_trim >/dev/null 2>&1; then
    action="$(deploy_trim "$action")"
  fi
  case "${action,,}" in
    install|1) do_install ;;
    update|2) do_update ;;
    backup|3) do_backup ;;
    status|4) do_status ;;
    uninstall|5) do_uninstall ;;
    menu|"") show_menu ;;
    q|quit|exit) exit 0 ;;
    *) error "$(t common.invalid_choice "$action")" ;;
  esac
}

# ----- lib/manager_cli.sh -----

manager_usage() {
  echo "$(t manager.usage "$0")" >&2
  echo "$(t manager.usage_examples "$0" "$0" "$0")" >&2
  echo "$(t manager.available_apps "$(deploy_app_ids | tr '\n' ' ' | sed 's/[[:space:]]*$//')")" >&2
}

show_manager_banner() {
  echo -e "\n${BOLD}${CYAN}$(t manager.title)${NC}"
  echo -e "$(t manager.description)\n"
}

show_manager_menu() {
  show_manager_banner
  echo "$(t manager.choose_app)"
  echo

  local index=1 app_id app_name
  for app_id in "${DEPLOY_APP_IDS[@]}"; do
    app_name="$(deploy_app_name_for "$app_id")"
    printf '  %s) %-16s %s\n' "$index" "$app_id" "$app_name"
    index=$((index + 1))
  done
  echo "  q) $(t common.quit)"
  echo

  prompt "$(t manager.selection_prompt)"
  local choice app_id status
  read -r choice
  set +e
  app_id="$(deploy_app_id_from_selection "$choice")"
  status=$?
  set -e
  if [[ "$status" -eq 2 ]]; then
    exit 0
  fi
  if [[ "$status" -ne 0 ]]; then
    error "$(t manager.invalid_app "$choice")"
  fi
  manager_load_app "$app_id"
  show_menu
}

manager_load_app() {
  local app_id="$1" app_file
  if [[ "${DEPLOY_BUNDLED_MANAGER:-0}" == "1" ]]; then
    BUNDLED_APP_IMPL_SCRIPT_NAME="install_${app_id}_impl.sh"
    manager_source_bundled_app_definition "$app_id"
    return 0
  fi
  app_file="$(deploy_app_file_for "$app_id")" || error "$(t manager.invalid_app "$app_id")"
  app_file="${DEPLOY_ROOT_DIR}/${app_file}"
  [[ -f "$app_file" ]] || error "$(t manager.app_file_missing "$app_file")"
  source "$app_file"
}

manager_source_bundled_app_definition() {
  local app_id="$1" marker
  marker="__DEPLOY_APP_DEFINITION__ ${app_id}"
  if ! grep -qxF "$marker" "${BASH_SOURCE[0]}"; then
    error "$(t manager.app_definition_missing "$app_id")"
  fi
  source <(
    awk -v marker="$marker" '
      $0 == marker { found=1; next }
      found && $0 == "__DEPLOY_APP_DEFINITION_END__" { exit }
      found { print }
    ' "${BASH_SOURCE[0]}"
  )
}

manager_list_apps() {
  local app_id app_name
  for app_id in "${DEPLOY_APP_IDS[@]}"; do
    app_name="$(deploy_app_name_for "$app_id")"
    printf '%-16s %s\n' "$app_id" "$app_name"
  done
}

manager_main() {
  local command="${1:-menu}" app_id status action
  command="$(deploy_trim "$command")"
  case "${command,,}" in
    menu|"")
      show_manager_menu
      ;;
    list|apps)
      manager_list_apps
      ;;
    help|-h|--help)
      manager_usage
      ;;
    q|quit|exit)
      exit 0
      ;;
    *)
      set +e
      app_id="$(deploy_app_id_from_selection "$command")"
      status=$?
      set -e
      if [[ "$status" -eq 2 ]]; then
        exit 0
      fi
      if [[ "$status" -ne 0 ]]; then
        manager_usage
        error "$(t manager.invalid_app "$command")"
      fi
      shift || true
      action="${1:-menu}"
      manager_load_app "$app_id"
      dispatch_action "$action"
      ;;
  esac
}

manager_main "$@"
exit 0

