  app.tickflow.summary.status_cmd \
  "show service status" \
  "查看服务状态" \
  app.tickflow.summary.logs_cmd \
  "follow logs" \
  "实时日志" \
  app.tickflow.summary.restart_cmd \
  "restart service" \
  "重启服务" \
  app.tickflow.summary.update_cmd \
  "update to the latest version" \
  "更新到最新版" \
  app.tickflow.summary.backup_cmd \
  "back up data now" \
  "立即备份数据" \
