LimitNPROC=64

# systemd sandboxing for defense in depth.
PrivateTmp=true
PrivateDevices=true
ProtectHome=true
ProtectSystem=strict
# Keep the filesystem read-only except for data and log directories.
ReadWritePaths=${VW_DATA_DIR} $(dirname "${VW_LOG_FILE}")

# Restart after failures.
