  then
    rm -f "$_vw_logrotate_tmp"
    error "$(t app.vaultwarden.error.logrotate)"
  fi
  if ! chmod 644 "$_vw_logrotate_tmp" \
      || ! chown root:root "$_vw_logrotate_tmp" \
      || ! mv "$_vw_logrotate_tmp" "$_vw_logrotate_file"; then
    rm -f "$_vw_logrotate_tmp"
    error "$(t app.vaultwarden.error.logrotate)"
  fi
  success "$(t app.vaultwarden.success.logrotate)"
  step "$(t app.vaultwarden.step.firewall)"
  local FW_DONE=false
  local FW_ERROR=false
  if command -v ufw &>/dev/null && ufw status 2>/dev/null | grep -q "Status: active"; then
    if ufw allow "Nginx Full" >/dev/null 2>&1; then
      success "$(t app.vaultwarden.success.ufw)"
      FW_DONE=true
    else
      FW_ERROR=true
    fi
  fi
  if ! $FW_DONE && command -v iptables &>/dev/null; then
    local iptables_ok=true
    for P in 80 443; do
      if ! iptables -C INPUT -p tcp --dport "$P" -j ACCEPT 2>/dev/null \
          && ! iptables -A INPUT -p tcp --dport "$P" -j ACCEPT; then
        iptables_ok=false
        break
      fi
    done
    if $iptables_ok; then
      success "$(t app.vaultwarden.success.iptables)"
      FW_DONE=true
      if command -v netfilter-persistent &>/dev/null; then
        if netfilter-persistent save 2>/dev/null; then
          success "$(t app.vaultwarden.success.iptables_saved)"
        else
          warn "$(t app.vaultwarden.warn.iptables_not_persisted)"
        fi
      else
        warn "$(t app.vaultwarden.warn.iptables_not_persisted)"
      fi
    else
      FW_ERROR=true
    fi
  fi
  if ! $FW_DONE; then
    if $FW_ERROR; then
      warn "$(t app.vaultwarden.warn.firewall_config_failed)"
    else
      warn "$(t app.vaultwarden.warn.no_firewall)"
    fi
  fi
  step "$(t app.vaultwarden.step.auto_backup)"
  _write_backup_script
  local _vw_cron_file="/etc/cron.d/vaultwarden-backup"
  local _vw_cron_tmp
  if ! _vw_cron_tmp=$(mktemp "${_vw_cron_file}.XXXXXX"); then
    error "$(t app.vaultwarden.error.auto_backup)"
  fi
  if ! printf '%s\n' "30 3 * * * root /bin/bash /usr/local/bin/vaultwarden-backup >> ${VW_BACKUP_DIR}/backup.log 2>&1" > "$_vw_cron_tmp" \
      || ! chmod 644 "$_vw_cron_tmp" \
      || ! chown root:root "$_vw_cron_tmp" \
      || ! mv "$_vw_cron_tmp" "$_vw_cron_file"; then
    rm -f "$_vw_cron_tmp"
    error "$(t app.vaultwarden.error.auto_backup)"
  fi
  success "$(t app.vaultwarden.success.auto_backup "$BACKUP_KEEP_DAYS")"
  step "$(t app.vaultwarden.step.health)"
  app_save_config
  local _hc_elapsed=0
  local HTTP_CODE
  until HTTP_CODE=$(curl -o /dev/null -s -w "%{http_code}" --max-time 5 "http://127.0.0.1:${VW_PORT}/" || echo "000") \
      && [[ "$HTTP_CODE" =~ ^(200|301|302)$ ]]; do
    sleep 1; _hc_elapsed=$(( _hc_elapsed + 1 ))
    [[ $_hc_elapsed -ge 10 ]] && break
  done
  if [[ "$HTTP_CODE" == "200" || "$HTTP_CODE" == "302" ]]; then
    success "$(t app.vaultwarden.success.local_health "$HTTP_CODE")"
    local _health_state="ready"
  else
    warn "$(t app.vaultwarden.warn.local_health "$HTTP_CODE")"
    warn "$(t app.vaultwarden.warn.debug)"
    local _health_state="pending"
  fi
  local INTERNAL_IP PROTO INSTALLED_VER
  INTERNAL_IP=$(hostname -I 2>/dev/null | awk '{print $1}' || true)
  INTERNAL_IP="${INTERNAL_IP:-YOUR_SERVER_IP}"
  if [[ "$ENABLE_HTTPS" == "true" ]]; then PROTO="https"; else PROTO="http"; fi
  INSTALLED_VER=$(get_installed_version)
  local _token_tmp
  if ! _token_tmp=$(mktemp /root/.vaultwarden-admin-token.XXXXXX); then
    error "$(t app.vaultwarden.error.admin_token_hash)"
  fi
  if ! chmod 600 "$_token_tmp" || ! printf '%s\n' "$ADMIN_PLAIN" > "$_token_tmp"; then
    rm -f "$_token_tmp"
    error "$(t app.vaultwarden.error.admin_token_hash)"
  fi
  echo ""
  echo -e "${BOLD}${GREEN}"
  echo "  ╔═══════════════════════════════════════════════════════════════╗"
  if [[ "$_health_state" == "pending" ]]; then
    echo "  ║             $(t app.vaultwarden.summary.title_pending)            ║"
  else
    echo "  ║             $(t app.vaultwarden.summary.title_ready)            ║"
  fi
  echo "  ╠═══════════════════════════════════════════════════════════════╣"
  echo -e "  ║  $(t app.vaultwarden.summary.url)    ${CYAN}${PROTO}://${VW_DOMAIN}${GREEN}"
  echo -e "  ║  $(t app.vaultwarden.summary.admin)  ${CYAN}${PROTO}://${VW_DOMAIN}/admin${GREEN}"
  echo -e "  ║  $(t app.vaultwarden.summary.lan)    ${CYAN}http://${INTERNAL_IP}:${VW_PORT}${GREEN}"
  echo "  ╠═══════════════════════════════════════════════════════════════╣"
  echo -e "  ║  $(t app.vaultwarden.summary.version)        ${YELLOW}${INSTALLED_VER}${GREEN}"
  echo -e "  ║  $(t app.vaultwarden.summary.binary)      ${YELLOW}${VW_BIN}${GREEN}"
  echo -e "  ║  $(t app.vaultwarden.summary.data)    ${YELLOW}${VW_DATA_DIR}${GREEN}"
  echo -e "  ║  Web Vault   ${YELLOW}${VW_WEB_DIR}${GREEN}"
  echo -e "  ║  $(t app.vaultwarden.summary.env)    ${YELLOW}${VW_ENV_FILE}${GREEN}  ($(t app.vaultwarden.summary.mode600))"
  echo -e "  ║  $(t app.vaultwarden.summary.log)        ${YELLOW}${VW_LOG_FILE}${GREEN}"
  echo -e "  ║  $(t app.vaultwarden.summary.backup)    ${YELLOW}${VW_BACKUP_DIR}${GREEN}"
  echo "  ╠═══════════════════════════════════════════════════════════════╣"
  echo -e "  ║  ${RED}${BOLD}$(t app.vaultwarden.summary.token_warning)${GREEN}"
  echo -e "  ║  $(t app.vaultwarden.summary.view_command) ${YELLOW}cat ${_token_tmp}${GREEN}"
  echo -e "  ║  $(t app.vaultwarden.summary.remove_command) ${YELLOW}rm -f ${_token_tmp}${GREEN}"
  echo "  ╚═══════════════════════════════════════════════════════════════╝"
  echo -e "${NC}"
  echo -e "  ${BOLD}$(t app.vaultwarden.summary.first_steps)${NC}"
  echo ""
  echo -e "  ${CYAN}# $(t app.vaultwarden.summary.step0)${NC}"
  echo -e "     cat ${_token_tmp}"
  echo -e "     rm -f ${_token_tmp}"
  echo ""
  echo -e "  ${CYAN}# $(t app.vaultwarden.summary.step1)${NC}"
  echo -e "     $(t app.vaultwarden.summary.create_account "${PROTO}://${VW_DOMAIN}")"
  echo ""
  echo -e "  ${CYAN}# $(t app.vaultwarden.summary.step2)${NC}"
  echo -e "     $(t app.vaultwarden.summary.method_admin "${PROTO}://${VW_DOMAIN}")"
  echo -e "     $(t app.vaultwarden.summary.method_config "$VW_ENV_FILE")"
  echo -e "              $(t app.vaultwarden.summary.then_restart)"
  echo ""
  echo -e "  ${CYAN}# $(t app.vaultwarden.summary.step3)${NC}"
  echo -e "     $(t app.vaultwarden.summary.self_hosted "${PROTO}://${VW_DOMAIN}")"
  echo ""
  echo -e "  ${CYAN}# $(t app.vaultwarden.summary.step4)${NC}"
  echo -e "     systemctl status vaultwarden          # $(t app.vaultwarden.summary.cmd_status)"
  echo -e "     journalctl -u vaultwarden -f          # $(t app.vaultwarden.summary.cmd_logs)"
  echo -e "     systemctl restart vaultwarden         # $(t app.vaultwarden.summary.cmd_restart)"
  echo -e "     vaultwarden-backup                    # $(t app.vaultwarden.summary.cmd_backup)"
  echo ""
  echo -e "  ${YELLOW}${BOLD}$(t app.vaultwarden.summary.important)${NC} $(t app.vaultwarden.summary.token_cleanup)"
  echo ""
}
do_update() {
  show_banner
  preflight_check
  app_load_config _VW_DERIVE_PATHS
  acquire_lock
  check_connectivity
  step "$(t app.vaultwarden.step.update)"
  [[ ! -x "$VW_BIN" ]] && error "$(t app.vaultwarden.error.not_installed_update)"
  local OLD_VER NEW_VER PLATFORM WORK_DIR NEW_BIN_PATH EXTRACTED_WEBVAULT_PATH
  OLD_VER=$(get_installed_version)
  info "$(t app.vaultwarden.info.current_version "$OLD_VER")"
  info "$(t app.vaultwarden.info.pre_update_backup)"
  if ! _backup_silent "pre-update"; then
    :
  fi
  local _pre_update_svc_state
  _pre_update_svc_state=$(systemctl is-active vaultwarden 2>/dev/null || echo "inactive")
  if [[ "$_pre_update_svc_state" == "failed" ]]; then
    warn "$(t app.vaultwarden.warn.pre_update_failed_state)"
    warn "$(t app.vaultwarden.warn.pre_update_existing_error)"
  fi
  info "$(t app.vaultwarden.info.stop_service)"
  systemctl stop vaultwarden 2>/dev/null || true
  case $ARCH in
    x86_64)  PLATFORM="linux/amd64"  ;;
    aarch64) PLATFORM="linux/arm64"  ;;
    armv7l)  PLATFORM="linux/arm/v7" ;;
    *)       error "$(t app.vaultwarden.error.arch "$ARCH")" ;;
  esac
  if ! WORK_DIR=$(mktemp -d /tmp/vaultwarden_update_XXXXXX); then
    error "$(t app.vaultwarden.error.image_extract)"
  fi
  _cleanup_update() {
    flock -u 9 2>/dev/null; exec 9>&- 2>/dev/null
    if [[ -d "${WORK_DIR:-}" ]]; then
      rm -rf "$WORK_DIR"
    fi
  }
  trap '_cleanup_update' EXIT
  step "$(t app.vaultwarden.step.extract_update_binary)"
  NEW_BIN_PATH=$(extract_binary "$WORK_DIR" "$PLATFORM")
  EXTRACTED_WEBVAULT_PATH=$(cat "${WORK_DIR}/.webvault_path" 2>/dev/null || true)
  backup_vaultwarden_binary "${VW_BIN}.bak.$(date +%Y%m%d%H%M%S)" \
    || error "$(t app.vaultwarden.error.binary_install "$VW_BIN")"
  install_vaultwarden_binary "$NEW_BIN_PATH" \
    || error "$(t app.vaultwarden.error.binary_install "$VW_BIN")"
  success "$(t app.vaultwarden.success.binary_updated)"
  NEW_VER=$(get_installed_version)
  step "$(t app.vaultwarden.step.update_web_vault)"
  local _wv_bak_ts="${VW_WEB_DIR}.bak.$(date +%Y%m%d%H%M%S)"
  if [[ -n "$EXTRACTED_WEBVAULT_PATH" && -d "$EXTRACTED_WEBVAULT_PATH" ]]; then
    if deploy_web_vault_from_dir "$EXTRACTED_WEBVAULT_PATH" "$_wv_bak_ts"; then
      success "$(t app.vaultwarden.success.web_vault_updated_image)"
    else
      warn "$(t app.vaultwarden.warn.web_vault_update_extract "$VW_WEB_DIR")"
    fi
  else
    local _fetched_wv_ver
    _fetched_wv_ver=$(get_latest_webvault_ver)
    if [[ -n "$_fetched_wv_ver" ]]; then
      local WV_URL="https://github.com/dani-garcia/bw_web_builds/releases/download/v${_fetched_wv_ver}/bw_web_v${_fetched_wv_ver}.tar.gz"
      if wget -q --show-progress -O "${WORK_DIR}/web-vault.tar.gz" "$WV_URL"; then
        if _verify_web_vault_archive "${WORK_DIR}/web-vault.tar.gz" nonfatal; then
          local _wv_extract_root="${WORK_DIR}/web-vault-extract"
          if ! mkdir -p "$_wv_extract_root"; then
            error "$(t app.vaultwarden.error.web_vault_extract_dir "$_wv_extract_root")"
          fi
          if tar -xzf "${WORK_DIR}/web-vault.tar.gz" -C "$_wv_extract_root"; then
            local _wv_source_dir
            _wv_source_dir=$(find "$_wv_extract_root" -type d -name "web-vault" | head -1 || true)
            if [[ -n "$_wv_source_dir" ]] && deploy_web_vault_from_dir "$_wv_source_dir" "$_wv_bak_ts"; then
              success "$(t app.vaultwarden.success.web_vault_updated_version "$_fetched_wv_ver")"
            else
              warn "$(t app.vaultwarden.warn.web_vault_update_extract "$VW_WEB_DIR")"
            fi
          else
            warn "$(t app.vaultwarden.warn.web_vault_update_extract "$VW_WEB_DIR")"
          fi
        else
          warn "$(t app.vaultwarden.warn.web_vault_update_extract "$VW_WEB_DIR")"
        fi
      else
        warn "$(t app.vaultwarden.warn.web_vault_update_download)"
      fi
    else
      warn "$(t app.vaultwarden.warn.web_vault_update_version)"
    fi
  fi
  app_check_port_conflict "$VW_PORT" "VW_PORT"
  if systemctl start vaultwarden && wait_for_service vaultwarden 20; then
    success "$(t app.vaultwarden.success.restart)"
    if [[ "$OLD_VER" != "$NEW_VER" ]]; then
      success "$(t app.vaultwarden.success.version_updated "$OLD_VER" "$NEW_VER")"
    else
      success "$(t app.vaultwarden.success.already_latest "$NEW_VER")"
    fi
  else
    warn "$(t app.vaultwarden.warn.restart_failed_rollback)"
    NEWEST_BAK=$(find "$(dirname "$VW_BIN")" -maxdepth 1 \
      -name "vaultwarden.bak.*" -type f -printf '%T@ %p\n' 2>/dev/null \
      | sort -rn | awk 'NR==1{print $2}' || true)
    if [[ -n "$NEWEST_BAK" ]]; then
      install_vaultwarden_binary "$NEWEST_BAK" \
        || error "$(t app.vaultwarden.error.rollback_start_failed)"
      if [[ -d "$_wv_bak_ts" ]]; then
        restore_web_vault_backup "$_wv_bak_ts" \
          || error "$(t app.vaultwarden.error.rollback_start_failed)"
        warn "$(t app.vaultwarden.warn.web_vault_rolled_back)"
      fi
      if systemctl start vaultwarden && wait_for_service vaultwarden 20; then
        success "$(t app.vaultwarden.success.rollback "$OLD_VER")"
        local _backup_kept
        _backup_kept=$(find "$(dirname "$VW_BIN")" -maxdepth 1 -name "vaultwarden.bak.*" -type f | sort -r | head -1 || t app.vaultwarden.status.not_installed)
        error "$(t app.vaultwarden.error.update_rolled_back "$OLD_VER" "$_backup_kept")"
      else
        error "$(t app.vaultwarden.error.rollback_start_failed)"
      fi
    else
      error "$(t app.vaultwarden.error.no_backup_binary)"
    fi
  fi
  local -a _old_baks
  mapfile -t _old_baks < <(find "$(dirname "$VW_BIN")" -maxdepth 1 \
    -name "vaultwarden.bak.*" -type f -printf '%T@ %p\n' 2>/dev/null \
    | sort -rn | awk 'NR>3{print $2}')
  if [[ ${#_old_baks[@]} -gt 0 ]]; then
    local _cleaned_old=0
    local _old_bak
    for _old_bak in "${_old_baks[@]}"; do
      if rm -f "$_old_bak"; then
        _cleaned_old=$(( _cleaned_old + 1 ))
      else
        warn "$(t app.vaultwarden.warn.cleanup_old_binary_failed "$_old_bak")"
      fi
    done
    if [[ $_cleaned_old -gt 0 ]]; then
      info "$(t app.vaultwarden.info.cleaned_old_binaries "$_cleaned_old")"
    fi
  fi
  local _wv_parent
  _wv_parent=$(dirname "$VW_WEB_DIR")
  local _wv_basename
  _wv_basename=$(basename "$VW_WEB_DIR")
  local -a _old_wv_baks
  mapfile -t _old_wv_baks < <(find "$_wv_parent" -maxdepth 1 \
    -name "${_wv_basename}.bak.*" -type d -printf '%T@ %p\n' 2>/dev/null \
    | sort -rn | awk 'NR>3{print $2}')
  if [[ ${#_old_wv_baks[@]} -gt 0 ]]; then
    local _cleaned_wv=0
    local _old_wv_bak
    for _old_wv_bak in "${_old_wv_baks[@]}"; do
      if rm -rf "$_old_wv_bak"; then
        _cleaned_wv=$(( _cleaned_wv + 1 ))
      else
        warn "$(t app.vaultwarden.warn.cleanup_old_webvault_failed "$_old_wv_bak")"
      fi
    done
    if [[ $_cleaned_wv -gt 0 ]]; then
      info "$(t app.vaultwarden.info.cleaned_webvault_backups "$_cleaned_wv")"
    fi
  fi
  app_save_config
}
_write_backup_script() {
  local backup_script="/usr/local/bin/vaultwarden-backup"
  local backup_tmp
  if ! backup_tmp=$(mktemp "${backup_script}.XXXXXX"); then
    error "$(t app.vaultwarden.error.backup_script)"
  fi
  if ! cat > "$backup_tmp" << 'BKSH'
#!/bin/bash
# Auto-generated Vaultwarden backup script.
set -euo pipefail
umask 077   # Backup files include secrets and must be root-readable only.
BKSH
  then
    rm -f "$backup_tmp"
    error "$(t app.vaultwarden.error.backup_script)"
  fi
  if ! cat >> "$backup_tmp" << BKSH_VARS
BACKUP_DIR="${VW_BACKUP_DIR}"
DATA_DIR="${VW_DATA_DIR}"
ENV_FILE="${VW_ENV_FILE}"
KEEP_DAYS="${BACKUP_KEEP_DAYS}"
[[ "\${KEEP_DAYS}" =~ ^[0-9]+$ ]] || KEEP_DAYS=0
MSG_DATA_MISSING="$(t app.vaultwarden.backup.script.data_missing)"
MSG_BACKUP_DIR_FAILED="$(t app.vaultwarden.backup.script.dir_failed)"
MSG_SQLITE_WARNING="$(t app.vaultwarden.backup.script.sqlite_warning)"
MSG_SUCCESS="$(t app.vaultwarden.backup.script.success)"
MSG_FAILED="$(t app.vaultwarden.backup.script.failed)"
MSG_CLEANED="$(t app.vaultwarden.backup.script.cleaned)"
BKSH_VARS
  then
    rm -f "$backup_tmp"
    error "$(t app.vaultwarden.error.backup_script)"
  fi
  if ! cat >> "$backup_tmp" << 'BKSH'
TIMESTAMP=$(date +%Y%m%d_%H%M%S)
ARCHIVE="${BACKUP_DIR}/vaultwarden_${TIMESTAMP}.tar.gz"
ARCHIVE_TMP="${ARCHIVE}.tmp"   # Write to a temp file before moving it into place.
if ! mkdir -p "${BACKUP_DIR}"; then
  printf '%s  '"${MSG_BACKUP_DIR_FAILED}"'\n' "$(date '+%Y-%m-%d %H:%M:%S')" "${BACKUP_DIR}" >&2
  exit 1
fi

# Refuse to create an empty archive when the data directory is missing.
if [[ ! -d "${DATA_DIR}" ]]; then
  printf '%s  '"${MSG_DATA_MISSING}"'\n' "$(date '+%Y-%m-%d %H:%M:%S')" "${DATA_DIR}"
  exit 1
fi

# Checkpoint SQLite WAL data before archiving.
if [[ -f "${DATA_DIR}/db.sqlite3" ]]; then
  sqlite3 "${DATA_DIR}/db.sqlite3" "PRAGMA wal_checkpoint(FULL);" 2>/dev/null || true
  # Warn about database corruption without blocking file-level backups.
  INTEGRITY=$(sqlite3 "${DATA_DIR}/db.sqlite3" "PRAGMA integrity_check;" 2>/dev/null || echo "error")
  if [[ "$INTEGRITY" != "ok" ]]; then
    printf '%s  '"${MSG_SQLITE_WARNING}"'\n' "$(date '+%Y-%m-%d %H:%M:%S')" "${INTEGRITY}"
  fi
fi

# Archive data and environment configuration, excluding logs.
DATA_PARENT=$(dirname "${DATA_DIR}")
DATA_BASE=$(basename "${DATA_DIR}")

# Include the environment file only when it exists.
TAR_EXTRA=()
[[ -f "${ENV_FILE}" ]] && TAR_EXTRA=(-C / "${ENV_FILE#/}")

# Move the completed archive into place atomically.
if tar -czf "${ARCHIVE_TMP}" \
  --exclude="*.log" \
  --exclude="*.log.*" \
  -C "${DATA_PARENT}" "${DATA_BASE}" \
  "${TAR_EXTRA[@]+"${TAR_EXTRA[@]}"}" >&2; then
  if mv "${ARCHIVE_TMP}" "${ARCHIVE}"; then
    ARCHIVE_SIZE=$(du -sh "${ARCHIVE}" | cut -f1)
    printf '%s  '"${MSG_SUCCESS}"'\n' "$(date '+%Y-%m-%d %H:%M:%S')" "${ARCHIVE}" "${ARCHIVE_SIZE}"
  else
    rm -f "${ARCHIVE_TMP}"
    printf '%s  %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "${MSG_FAILED}"
    exit 1
  fi
else
  rm -f "${ARCHIVE_TMP}"
  printf '%s  %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "${MSG_FAILED}"
  exit 1
fi

# Remove expired backups.
if [[ "${KEEP_DAYS}" -gt 0 ]]; then
  REMOVED=$(find "${BACKUP_DIR}" -maxdepth 1 -name "vaultwarden_*.tar.gz" -mtime +"${KEEP_DAYS}" -print -delete | wc -l)
  if [[ "${REMOVED}" -gt 0 ]]; then
    printf '%s  '"${MSG_CLEANED}"'\n' "$(date '+%Y-%m-%d %H:%M:%S')" "${REMOVED}" "${KEEP_DAYS}"
  fi
fi
BKSH
  then
    rm -f "$backup_tmp"
    error "$(t app.vaultwarden.error.backup_script)"
  fi
  if ! chmod 750 "$backup_tmp" \
      || ! chown root:root "$backup_tmp" \
      || ! mv "$backup_tmp" "$backup_script"; then
    rm -f "$backup_tmp"
    error "$(t app.vaultwarden.error.backup_script)"
  fi
}
_backup_silent() {
  local label="${1:-manual}"
  local backup_log="${VW_BACKUP_DIR}/backup.log"
  _log_backup_helper() {
    [[ -d "$VW_BACKUP_DIR" ]] || return 1
    printf '%s  %s\n' "$(date '+%F %T')" "$1" >> "$backup_log"
  }
  if ! mkdir -p "$VW_BACKUP_DIR"; then
    warn "$(t app.vaultwarden.warn.backup_dir_failed "$VW_BACKUP_DIR")"
    return 1
  fi
  local archive="${VW_BACKUP_DIR}/vaultwarden_${label}_$(date +%Y%m%d_%H%M%S).tar.gz"
  local archive_tmp="${archive}.tmp"
  if [[ ! -d "$VW_DATA_DIR" ]]; then
    _log_backup_helper "$(t app.vaultwarden.backup.script.data_missing "$VW_DATA_DIR")"
    warn "$(t app.vaultwarden.warn.backup_data_missing "$VW_DATA_DIR")"
    return 1
  fi
  if [[ -f "${VW_DATA_DIR}/db.sqlite3" ]]; then
    sqlite3 "${VW_DATA_DIR}/db.sqlite3" "PRAGMA wal_checkpoint(FULL);" 2>/dev/null || true
    local _ic
    _ic=$(sqlite3 "${VW_DATA_DIR}/db.sqlite3" "PRAGMA integrity_check;" 2>/dev/null || echo "error")
    if [[ "$_ic" != "ok" ]]; then
      _log_backup_helper "$(t app.vaultwarden.backup.script.sqlite_warning "$_ic")"
      warn "$(t app.vaultwarden.warn.sqlite_integrity "$_ic")"
    fi
  fi
  local tar_extra=()
  [[ -f "$VW_ENV_FILE" ]] && tar_extra=(-C / "${VW_ENV_FILE#/}")
  if tar -czf "$archive_tmp" --exclude="*.log" --exclude="*.log.*" \
    -C "$(dirname "$VW_DATA_DIR")" "$(basename "$VW_DATA_DIR")" \
    "${tar_extra[@]+"${tar_extra[@]}"}" >&2; then
    if mv "$archive_tmp" "$archive"; then
      success "$(t app.vaultwarden.success.backup_created "$archive")"
    else
      rm -f "$archive_tmp"
      _log_backup_helper "$(t app.vaultwarden.backup.script.failed)"
      warn "$(t app.vaultwarden.warn.backup_failed_continue)"
      return 1
    fi
  else
    rm -f "$archive_tmp"
    _log_backup_helper "$(t app.vaultwarden.backup.script.failed)"
    warn "$(t app.vaultwarden.warn.backup_failed_continue)"
    return 1
  fi
}
do_backup() {
  show_banner
  [[ $EUID -ne 0 ]] && error "$(t error.root_required "$0" "")"
  app_load_config _VW_DERIVE_PATHS
  acquire_lock
  step "$(t app.vaultwarden.step.manual_backup)"
  [[ ! -d "$VW_DATA_DIR" ]] && error "$(t app.vaultwarden.error.data_missing_install "$VW_DATA_DIR")"
  local _backup_failed=0
  if ! _backup_silent "manual"; then
    _backup_failed=1
  fi
  echo ""
  info "$(t app.vaultwarden.info.backup_list)"
  mapfile -t _bak_list < <(
    find "${VW_BACKUP_DIR}" -maxdepth 1 -name "vaultwarden_*.tar.gz" \
      -printf '%T@ %p\n' 2>/dev/null | sort -rn | head -10 | awk '{print $2}'
  )
  if [[ ${#_bak_list[@]} -gt 0 ]]; then
    local _sz
    for _f in "${_bak_list[@]}"; do
      _sz=$(du -sh "$_f" 2>/dev/null | cut -f1 || echo "?")
      printf '  %-60s  %s\n' "$_f" "$_sz"
    done
  else
    warn "$(t app.vaultwarden.warn.no_backups)"
  fi
  echo ""
  local _total _total_size
  _total=$(find "${VW_BACKUP_DIR}" -maxdepth 1 -name "vaultwarden_*.tar.gz" 2>/dev/null | wc -l)
  _total_size=$(du -sh "${VW_BACKUP_DIR}" 2>/dev/null | cut -f1 || echo "0")
  info "$(t app.vaultwarden.info.backup_total "$_total" "$_total_size")"
  if [[ "$_backup_failed" -ne 0 ]]; then
    error "$(t app.vaultwarden.error.manual_backup_failed)"
  fi
  release_lock
}
do_status() {
  local DB_SIZE CERT_PATH EXPIRY DAYS HTTP_CODE
  show_banner
  app_load_config _VW_DERIVE_PATHS
  if [[ $EUID -ne 0 ]]; then
    warn "$(t app.vaultwarden.warn.non_root_status)"
    warn "$(t app.vaultwarden.warn.root_status "$0")"
  fi
  step "$(t app.vaultwarden.step.status)"
  echo -e "\n${BOLD}[$(t app.vaultwarden.status.systemd)]${NC}"
  systemctl status vaultwarden --no-pager -l 2>/dev/null | head -15 | sed 's/^/  /' \
    || echo -e "  ${RED}[✗]${NC} $(t app.vaultwarden.status.service_missing)"
  echo -e "\n${BOLD}[$(t app.vaultwarden.status.version_info)]${NC}"
  if [[ -x "$VW_BIN" ]]; then
    local _bin_size _bin_time
    _bin_size=$(du -sh "$VW_BIN" 2>/dev/null | cut -f1 || t status.unknown)
    _bin_time=$(stat -c '%y' "$VW_BIN" 2>/dev/null | cut -d'.' -f1 || t status.unknown)
    echo -e "  $(t app.vaultwarden.status.binary_version "$(get_installed_version)")"
    echo -e "  $(t app.vaultwarden.status.binary_path "$VW_BIN" "$_bin_size")"
    echo -e "  $(t app.vaultwarden.status.binary_time "$_bin_time")"
  else
    echo -e "  ${RED}[✗]${NC} $(t app.vaultwarden.status.binary_missing "$VW_BIN")"
  fi
  echo -e "\n${BOLD}[$(t app.vaultwarden.status.data_dir "$VW_DATA_DIR")]${NC}"
  if [[ -d "$VW_DATA_DIR" ]]; then
    ls -lh "${VW_DATA_DIR}" 2>/dev/null | tail -n +2 | awk '{printf "  %-12s  %s\n", $5, $NF}' || true
    echo "  ──────────────────────────"
    local _data_size
    _data_size=$(du -sh "$VW_DATA_DIR" 2>/dev/null | cut -f1 || t status.unknown)
    echo "  $(t app.vaultwarden.status.total "$_data_size")"
    if [[ -f "${VW_DATA_DIR}/db.sqlite3" ]]; then
      DB_SIZE=$(du -sh "${VW_DATA_DIR}/db.sqlite3" 2>/dev/null | cut -f1 || t status.unknown)
      echo -e "  $(t app.vaultwarden.status.database "$DB_SIZE")"
    fi
  else
    echo -e "  ${RED}[✗]${NC} $(t app.vaultwarden.status.data_missing)"
  fi
  echo -e "\n${BOLD}[$(t app.vaultwarden.status.backup_files)]${NC}"
  if find "${VW_BACKUP_DIR}" -maxdepth 1 -name "vaultwarden_*.tar.gz" 2>/dev/null | grep -q .; then
    ls -lht "${VW_BACKUP_DIR}"/vaultwarden_*.tar.gz 2>/dev/null | head -5 \
      | awk '{printf "  %-60s  %s\n", $NF, $5}'
    echo -e "  $(t app.vaultwarden.status.backup_count "$(find "${VW_BACKUP_DIR}" -maxdepth 1 -name "vaultwarden_*.tar.gz" 2>/dev/null | wc -l)")"
  else
    echo -e "  ${YELLOW}[!]${NC} $(t app.vaultwarden.warn.no_backups)"
  fi
  echo -e "\n${BOLD}[$(t app.vaultwarden.status.nginx)]${NC}"
  systemctl is-active nginx &>/dev/null \
    && echo -e "  ${GREEN}[✓]${NC} $(t app.vaultwarden.status.nginx_running)" \
    || echo -e "  ${RED}[✗]${NC} $(t app.vaultwarden.status.nginx_stopped)"
  echo -e "\n${BOLD}[$(t app.vaultwarden.status.fail2ban)]${NC}"
  if systemctl is-active fail2ban &>/dev/null; then
    fail2ban-client status vaultwarden 2>/dev/null | sed 's/^/  /' \
      || echo -e "  ${YELLOW}[!]${NC} $(t app.vaultwarden.status.fail2ban_jail_missing)"
  else
    echo -e "  ${RED}[✗]${NC} $(t app.vaultwarden.status.fail2ban_stopped)"
  fi
  echo -e "\n${BOLD}[$(t app.vaultwarden.status.http_health)]${NC}"
  HTTP_CODE=$(curl -o /dev/null -s -w "%{http_code}" --max-time 5 "http://127.0.0.1:${VW_PORT}/" 2>/dev/null || echo "000")
  [[ "$HTTP_CODE" =~ ^(200|302|301)$ ]] \
    && echo -e "  ${GREEN}[✓]${NC} $(t app.vaultwarden.status.local_response "$HTTP_CODE")" \
    || echo -e "  ${YELLOW}[!]${NC} $(t app.vaultwarden.status.local_response_warn "$HTTP_CODE")"
  echo -e "\n${BOLD}[$(t app.vaultwarden.status.tls)]${NC}"
  CERT_PATH="/etc/letsencrypt/live/${VW_DOMAIN}/fullchain.pem"
  if [[ -f "$CERT_PATH" ]]; then
    EXPIRY=$(openssl x509 -enddate -noout -in "$CERT_PATH" | sed 's/notAfter=//')
    DAYS=$(( ( $(date -d "$EXPIRY" +%s 2>/dev/null || echo 0) - $(date +%s) ) / 86400 ))
    if [[ $DAYS -gt 30 ]]; then
      echo -e "  ${GREEN}[✓]${NC} $(t app.vaultwarden.status.cert_valid "$DAYS" "$EXPIRY")"
    elif [[ $DAYS -gt 0 ]]; then
      echo -e "  ${YELLOW}[!]${NC} $(t app.vaultwarden.status.cert_expiring "$DAYS")"
    else
      echo -e "  ${RED}[✗]${NC} $(t app.vaultwarden.status.cert_expired "$DAYS")"
    fi
  else
    echo -e "  ${YELLOW}[!]${NC} $(t app.vaultwarden.status.cert_missing)"
  fi
  echo ""
}
do_uninstall() {
  show_banner
  preflight_check
  app_load_config _VW_DERIVE_PATHS
  acquire_lock
  [[ -z "${VW_BIN:-}"        ]] && error "$(t app.vaultwarden.error.bin_empty)"
  [[ -z "${VW_DATA_DIR:-}"   ]] && error "$(t app.vaultwarden.error.data_dir_empty)"
  [[ -z "${VW_BACKUP_DIR:-}" ]] && error "$(t app.vaultwarden.error.backup_dir_empty)"
  [[ "${VW_DATA_DIR}"   == "/" ]] && error "$(t app.vaultwarden.error.data_dir_root)"
  [[ "${VW_BACKUP_DIR}" == "/" ]] && error "$(t app.vaultwarden.error.backup_dir_root)"
  step "$(t app.vaultwarden.step.uninstall)"
  echo -e "${RED}${BOLD}"
  echo "  $(t app.vaultwarden.uninstall.removes)"
  echo "     - $(t app.vaultwarden.uninstall.binary "$VW_BIN")"
  echo "     - $(t app.vaultwarden.uninstall.systemd)"
  echo "     - $(t app.vaultwarden.uninstall.nginx)"
  echo "     - $(t app.vaultwarden.uninstall.fail2ban)"
  echo "     - $(t app.vaultwarden.uninstall.env "$VW_ENV_FILE")"
  echo "     - $(t app.vaultwarden.uninstall.cron)"
  echo "  $(t app.vaultwarden.uninstall.keep_data "$VW_DATA_DIR")"
  echo -e "${NC}"
  prompt "$(t app.vaultwarden.prompt.continue)"
  read -r _c
  [[ "$_c" != "YES" ]] && { info "$(t app.vaultwarden.info.cancelled)"; exit 0; }
  prompt "$(t app.vaultwarden.prompt.delete_data "$VW_DATA_DIR")"
  local _del_data; read -r _del_data
  local DELETE_DATA=false; [[ "${_del_data,,}" == "y" ]] && DELETE_DATA=true
  prompt "$(t app.vaultwarden.prompt.delete_backup "$VW_BACKUP_DIR")"
  local _del_bak; read -r _del_bak
  local DELETE_BACKUP=false; [[ "${_del_bak,,}" == "y" ]] && DELETE_BACKUP=true
  info "$(t app.vaultwarden.info.stop_service)"
  systemctl stop    vaultwarden 2>/dev/null || true
  systemctl disable vaultwarden 2>/dev/null || true
  rm -f /etc/systemd/system/vaultwarden.service
  if ! systemctl daemon-reload; then
    error "$(t app.vaultwarden.error.systemd_reload)"
  fi
  success "$(t app.vaultwarden.success.removed_systemd)"
  rm -f "${VW_BIN}"
  require_safe_path "VW_BIN_DIR" "$(dirname "$VW_BIN")"
  local _cleanup_path
  while IFS= read -r -d '' _cleanup_path; do
    if ! rm -f "$_cleanup_path"; then
      warn "$(t app.vaultwarden.warn.cleanup_old_binary_failed "$_cleanup_path")"
    fi
  done < <(find "$(dirname "$VW_BIN")" -maxdepth 1 -name "vaultwarden.bak.*" -type f -print0 2>/dev/null)
  success "$(t app.vaultwarden.success.removed_binary)"
  rm -f /etc/nginx/sites-enabled/vaultwarden /etc/nginx/sites-available/vaultwarden
  if command -v nginx >/dev/null 2>&1; then
    if nginx -t >/dev/null 2>&1; then
      systemctl reload nginx >/dev/null 2>&1 || nginx -t >&2 || true
    else
      nginx -t >&2 || true
    fi
  fi
  success "$(t app.vaultwarden.success.removed_nginx)"
  rm -f /etc/fail2ban/filter.d/vaultwarden.conf \
        /etc/fail2ban/filter.d/vaultwarden-admin.conf \
        /etc/fail2ban/jail.d/vaultwarden.conf
  if ! systemctl restart fail2ban 2>/dev/null; then
    warn "$(t app.vaultwarden.warn.fail2ban_restart)"
  fi
  success "$(t app.vaultwarden.success.removed_fail2ban)"
  rm -f /etc/cron.d/vaultwarden-backup \
        /usr/local/bin/vaultwarden-backup \
        /etc/logrotate.d/vaultwarden
  success "$(t app.vaultwarden.success.removed_scheduled)"
  rm -f "$VW_ENV_FILE" "$CONF_FILE"
  success "$(t app.vaultwarden.success.removed_config)"
  local _log_dir
  _log_dir=$(dirname "$VW_LOG_FILE")
  if [[ -n "$_log_dir" && "$_log_dir" != "." && "$_log_dir" != "/" && -d "$_log_dir" ]]; then
    safe_rm_dir "$_log_dir" "LOG_DIR"
    success "$(t app.vaultwarden.success.deleted_log "$_log_dir")"
  else
    warn "$(t app.vaultwarden.warn.log_path "$_log_dir")"
  fi
  if $DELETE_DATA; then
    safe_rm_dir "$VW_DATA_DIR" "VW_DATA_DIR"
    success "$(t app.vaultwarden.success.deleted_data "$VW_DATA_DIR")"
  else
    info "$(t app.vaultwarden.info.kept_data "$VW_DATA_DIR")"
  fi
  if $DELETE_BACKUP; then
    safe_rm_dir "$VW_BACKUP_DIR" "VW_BACKUP_DIR"
    success "$(t app.vaultwarden.success.deleted_backup "$VW_BACKUP_DIR")"
  else
    info "$(t app.vaultwarden.info.kept_backup "$VW_BACKUP_DIR")"
  fi
  if $DELETE_DATA && id "$VW_USER" &>/dev/null; then
    if userdel "$VW_USER" 2>/dev/null; then
      success "$(t app.vaultwarden.success.deleted_user "$VW_USER")"
    fi
  fi
  echo ""
  echo -e "${BOLD}${GREEN}  $(t app.vaultwarden.success.uninstalled)${NC}"
  if ! $DELETE_DATA; then
    echo -e "  ${YELLOW}[hint]${NC} $(t app.vaultwarden.hint.data_kept "$VW_DATA_DIR")"
    echo -e "  ${YELLOW}[hint]${NC} $(t app.vaultwarden.hint.remove_data "$VW_DATA_DIR")"
  fi
  echo ""
}
__DEPLOY_APP_IMPL_SCRIPT_END__

__DEPLOY_APP_IMPL_SCRIPT__ install_cyberstrikeai_impl.sh
#!/usr/bin/env bash
set -euo pipefail
umask 077
CSAI_DOMAIN="${CSAI_DOMAIN:-}"
PORT="${PORT:-8083}"
PUBLIC_PORT="${PUBLIC_PORT:-80}"
INSTALL_DIR="${INSTALL_DIR:-/opt/cyberstrike-ai}"
SERVICE_NAME="${SERVICE_NAME:-cyberstrike-ai}"
SERVICE_USER="${SERVICE_USER:-cyberstrike}"
GITHUB_REPO="${GITHUB_REPO:-Ed1s0nZ/CyberStrikeAI}"
GITHUB_BRANCH="${GITHUB_BRANCH:-main}"
BACKUP_DIR="${BACKUP_DIR:-/opt/cyberstrike-ai-backups}"
BACKUP_KEEP_DAYS="${BACKUP_KEEP_DAYS:-30}"
ENABLE_NGINX="${ENABLE_NGINX:-true}"
CSAI_HTTPS="${CSAI_HTTPS:-true}"
OPEN_FIREWALL="${OPEN_FIREWALL:-true}"
PIP_INDEX_URL="${PIP_INDEX_URL:-https://pypi.tuna.tsinghua.edu.cn/simple}"
GOPROXY="${GOPROXY:-https://goproxy.cn,direct}"
BIN_NAME="cyberstrike-ai"
BIN_PATH="${INSTALL_DIR}/${BIN_NAME}"
CONFIG_FILE="${INSTALL_DIR}/config.yaml"
VENV_DIR="${INSTALL_DIR}/venv"
LOG_DIR="${INSTALL_DIR}/logs"
NGINX_CONF="/etc/nginx/sites-available/cyberstrike-ai"
NGINX_LINK="/etc/nginx/sites-enabled/cyberstrike-ai"
BACKUP_SCRIPT="/usr/local/bin/cyberstrike-ai-backup"
CRON_FILE="/etc/cron.d/cyberstrike-ai-backup"
LOGROTATE_FILE="/etc/logrotate.d/cyberstrike-ai"
CONFIG_KEYS=(
  CSAI_DOMAIN PORT PUBLIC_PORT INSTALL_DIR SERVICE_NAME SERVICE_USER
  GITHUB_REPO GITHUB_BRANCH BACKUP_DIR BACKUP_KEEP_DAYS ENABLE_NGINX
  CSAI_HTTPS OPEN_FIREWALL PIP_INDEX_URL GOPROXY
)
_CSAI_DERIVE_PATHS() {
  BIN_PATH="${INSTALL_DIR}/${BIN_NAME}"
  CONFIG_FILE="${INSTALL_DIR}/config.yaml"
  VENV_DIR="${INSTALL_DIR}/venv"
  LOG_DIR="${INSTALL_DIR}/logs"
}
_bool_true() {
  case "${1,,}" in
    1|true|yes|y|on) return 0 ;;
    *) return 1 ;;
  esac
}
app_conf_register_legacy "/etc/cyberstrike-ai-deploy.conf"
CONF_FILE="$(app_conf_file)"
LOCK_FILE="$(app_lock_file)"
_validate_config_values() {
  app_validate_port "$PORT" "PORT"
  app_validate_port "$PUBLIC_PORT" "PUBLIC_PORT"
  app_validate_domain "CSAI_DOMAIN" "$CSAI_DOMAIN"
  app_validate_bool "ENABLE_NGINX" "$ENABLE_NGINX"
  app_validate_bool "CSAI_HTTPS" "$CSAI_HTTPS"
  app_validate_bool "OPEN_FIREWALL" "$OPEN_FIREWALL"
}
preflight_check() {
  [[ $EUID -eq 0 ]] || error "$(t error.root_required "$0" "${1:-}")"
  command -v apt-get >/dev/null 2>&1 || error "$(t app.cyberstrikeai.error.apt_only)"
  command -v systemctl >/dev/null 2>&1 || error "$(t app.cyberstrikeai.error.systemd_required)"
  local arch
  arch=$(uname -m)
  case "$arch" in
    x86_64|aarch64|arm64) ;;
    *) error "$(t app.cyberstrikeai.error.arch "$arch")" ;;
  esac
  _validate_config_values
}
check_connectivity() {
  check_connectivity_urls \
    "https://api.github.com" \
    "https://github.com" \
    "https://objects.githubusercontent.com" && return 0
  error "$(t app.cyberstrikeai.error.github_unreachable)"
}
restore_old_go_toolchain() {
  local old_go_backup="$1"
  [[ -n "$old_go_backup" && -e "$old_go_backup" ]] || return 0
  [[ ! -e /usr/local/go ]] || return 1
  mv "$old_go_backup" /usr/local/go
}
write_tool_symlink() {
  local target="$1" link_path="$2"
  if ! atomic_symlink "$target" "$link_path"; then
    error "$(t app.cyberstrikeai.error.go_failed)"
  fi
}
write_backup_file() {
  local source_path="$1" backup_path="$2"
  [[ -f "$source_path" ]] || return 0
  atomic_copy_file "$source_path" "$backup_path"
}
apt_install_base() {
  step "$(t app.cyberstrikeai.step.install_deps)"
  if ! apt-get update -qq; then
    error "$(t app.cyberstrikeai.error.apt_update)"
  fi
  if ! apt-get install -y -qq \
    ca-certificates curl git build-essential \
    python3 python3-venv python3-pip \
    sqlite3 tar gzip openssl lsof; then
    error "$(t app.cyberstrikeai.error.deps_install)"
  fi
  if _bool_true "$ENABLE_NGINX"; then
    if ! apt-get install -y -qq nginx; then
      error "$(t app.cyberstrikeai.error.nginx_deps_install)"
    fi
  fi
  success "$(t app.cyberstrikeai.success.deps)"
}
install_go_if_needed() {
  local need_install=false
  if ! command -v go >/dev/null 2>&1; then
    need_install=true
  else
    local ver major minor
    ver=$(go version | awk '{print $3}' | sed 's/^go//')
    major="${ver%%.*}"
    minor="${ver#*.}"; minor="${minor%%.*}"
    if [[ "$major" -lt 1 || ( "$major" -eq 1 && "$minor" -lt 21 ) ]]; then
      need_install=true
      warn "$(t app.cyberstrikeai.warn.go_old "$ver")"
    fi
  fi
  if ! $need_install; then
    success "$(t app.cyberstrikeai.success.go_ready "$(go version)")"
    return 0
  fi
  step "$(t app.cyberstrikeai.step.install_go)"
  if ! apt-get install -y -qq golang-go; then
    warn "$(t app.cyberstrikeai.warn.go_repo_install_failed)"
  fi
  if command -v go >/dev/null 2>&1; then
    local ver major minor
    ver=$(go version | awk '{print $3}' | sed 's/^go//')
    major="${ver%%.*}"
    minor="${ver#*.}"; minor="${minor%%.*}"
    if [[ "$major" -gt 1 || ( "$major" -eq 1 && "$minor" -ge 21 ) ]]; then
      success "$(t app.cyberstrikeai.success.go_installed "$(go version)")"
      return 0
    fi
    warn "$(t app.cyberstrikeai.warn.go_repo_old "$ver")"
  fi
  local arch go_arch latest_json version tarball url tmp extract_dir old_go_backup
  arch=$(uname -m)
  case "$arch" in
    x86_64) go_arch="amd64" ;;
    aarch64|arm64) go_arch="arm64" ;;
    *) error "$(t app.cyberstrikeai.error.go_arch "$arch")" ;;
  esac
  latest_json=$(curl -fsSL --max-time 20 "https://go.dev/dl/?mode=json" 2>/dev/null) \
    || error "$(t app.cyberstrikeai.error.go_query)"
  version=$(printf '%s\n' "$latest_json" | grep -oE '"version"[[:space:]]*:[[:space:]]*"go[0-9]+\.[0-9]+(\.[0-9]+)?"' | head -1 | sed 's/.*"\(go[^"]*\)".*/\1/' || true)
  [[ -n "$version" ]] || error "$(t app.cyberstrikeai.error.go_parse)"
  tarball="${version}.linux-${go_arch}.tar.gz"
  url="https://go.dev/dl/${tarball}"
  if ! tmp=$(mktemp); then
    error "$(t app.cyberstrikeai.error.go_query)"
  fi
  info "$(t app.cyberstrikeai.info.download "$url")"
  if ! curl -fL --retry 3 --connect-timeout 15 -o "$tmp" "$url"; then
    rm -f "$tmp"
    error "$(t app.cyberstrikeai.error.go_query)"
  fi
  if [[ ! -s "$tmp" ]]; then
    rm -f "$tmp"
    error "$(t app.cyberstrikeai.error.go_empty)"
  fi
  if ! extract_dir=$(mktemp -d /usr/local/go.extract.XXXXXX); then
    rm -f "$tmp"
    error "$(t app.cyberstrikeai.error.go_extract)"
  fi
  if ! tar -C "$extract_dir" -xzf "$tmp" || [[ ! -d "$extract_dir/go" ]]; then
    rm -f "$tmp"
    rm -rf "$extract_dir"
    error "$(t app.cyberstrikeai.error.go_extract)"
  fi
  rm -f "$tmp"
  old_go_backup=""
  if [[ -e /usr/local/go ]]; then
    if ! old_go_backup=$(mktemp -d /usr/local/go.previous.XXXXXX); then
      rm -rf "$extract_dir"
      error "$(t app.cyberstrikeai.error.go_failed)"
    fi
    if ! rmdir "$old_go_backup"; then
      rm -rf "$extract_dir" "$old_go_backup"
      error "$(t app.cyberstrikeai.error.go_failed)"
    fi
    if ! mv /usr/local/go "$old_go_backup"; then
      rm -rf "$extract_dir"
      error "$(t app.cyberstrikeai.error.go_failed)"
    fi
  fi
  if ! mv "$extract_dir/go" /usr/local/go; then
    if [[ -n "$old_go_backup" && -e "$old_go_backup" && ! -e /usr/local/go ]]; then
      if ! restore_old_go_toolchain "$old_go_backup"; then
        warn "$(t app.cyberstrikeai.warn.go_restore_failed)"
      fi
    fi
    rm -rf "$extract_dir"
    error "$(t app.cyberstrikeai.error.go_failed)"
  fi
  rm -rf "$extract_dir"
  if [[ -n "$old_go_backup" ]]; then
    rm -rf "$old_go_backup"
  fi
  write_tool_symlink /usr/local/go/bin/go /usr/local/bin/go \
    || error "$(t app.cyberstrikeai.error.go_failed)"
  write_tool_symlink /usr/local/go/bin/gofmt /usr/local/bin/gofmt \
    || error "$(t app.cyberstrikeai.error.go_failed)"
  hash -r 2>/dev/null || true
  command -v go >/dev/null 2>&1 || error "$(t app.cyberstrikeai.error.go_failed)"
  success "$(t app.cyberstrikeai.success.go_installed "$(go version)")"
}
ensure_service_user() {
  if ! id "$SERVICE_USER" >/dev/null 2>&1; then
    if ! useradd --system --home "$INSTALL_DIR" --shell /usr/sbin/nologin "$SERVICE_USER"; then
      error "$(t app.cyberstrikeai.error.user_create "$SERVICE_USER")"
    fi
    success "$(t app.cyberstrikeai.success.user_created "$SERVICE_USER")"
  fi
}
sync_repo_branch() {
  if ! git -C "$INSTALL_DIR" fetch --prune origin "$GITHUB_BRANCH"; then
    error "$(t app.cyberstrikeai.error.repo_fetch "$GITHUB_BRANCH" "$INSTALL_DIR" "$INSTALL_DIR" "$GITHUB_BRANCH")"
  fi
  if ! git -C "$INSTALL_DIR" checkout -q "$GITHUB_BRANCH"; then
    error "$(t app.cyberstrikeai.error.repo_checkout "$INSTALL_DIR" "$GITHUB_BRANCH" "$INSTALL_DIR" "$GITHUB_BRANCH")"
  fi
  if ! git -C "$INSTALL_DIR" pull --ff-only origin "$GITHUB_BRANCH"; then
    error "$(t app.cyberstrikeai.error.repo_pull "$INSTALL_DIR" "$GITHUB_BRANCH" "$INSTALL_DIR" "$GITHUB_BRANCH")"
  fi
}
clone_or_update_repo() {
  step "$(t app.cyberstrikeai.step.fetch_source)"
  if ! mkdir -p "$(dirname "$INSTALL_DIR")"; then
    error "$(t app.cyberstrikeai.error.source_parent_dir "$INSTALL_DIR")"
  fi
  if [[ -d "$INSTALL_DIR/.git" ]]; then
    info "$(t app.cyberstrikeai.info.repo_fetch "$GITHUB_BRANCH")"
    sync_repo_branch
  elif [[ -d "$INSTALL_DIR" && -n "$(ls -A "$INSTALL_DIR" 2>/dev/null)" ]]; then
    error "$(t app.cyberstrikeai.error.nonempty_dir "$INSTALL_DIR")"
  else
    safe_rm_dir "$INSTALL_DIR" "INSTALL_DIR"
    if ! git clone --depth 1 --branch "$GITHUB_BRANCH" "https://github.com/${GITHUB_REPO}.git" "$INSTALL_DIR"; then
      safe_rm_dir "$INSTALL_DIR" "INSTALL_DIR"
      error "$(t app.cyberstrikeai.error.repo_clone "$GITHUB_REPO" "$INSTALL_DIR" "$GITHUB_BRANCH" "$GITHUB_REPO" "$INSTALL_DIR")"
    fi
  fi
  success "$(t app.cyberstrikeai.success.source_ready "$INSTALL_DIR")"
}
patch_config_port_and_paths() {
  [[ -f "$CONFIG_FILE" ]] || error "$(t app.cyberstrikeai.error.config_missing "$CONFIG_FILE")"
  local backup="${CONFIG_FILE}.bak.$(date +%Y%m%d_%H%M%S)"
  write_backup_file "$CONFIG_FILE" "$backup" \
    || error "$(t app.cyberstrikeai.error.backup_write "$backup")"
  python3 - "$CONFIG_FILE" "$PORT" "$LOG_DIR/cyberstrike-ai.log" "$CSAI_HTTPS" <<'PY'
import os
from pathlib import Path
import re
import sys
import tempfile

path = Path(sys.argv[1])
port = sys.argv[2]
log_file = sys.argv[3]
https_enabled = sys.argv[4].strip().lower() in {"1", "true", "yes", "y", "on"}
text = path.read_text(encoding="utf-8")
file_stat = path.stat()

def replace_in_section(src, section, key, value):
    pattern = re.compile(
        rf"(^[ \t]*{re.escape(section)}:[^\n]*\n)(.*?)(?=^[^ \t#][^:\n]*:|\Z)",
        re.M | re.S,
    )
    m = pattern.search(src)
    if not m:
        return src + f"\n{section}:\n  {key}: {value}\n"
    block = m.group(2)
    key_pattern = re.compile(rf"(^[ \t]*{re.escape(key)}:[^\n]*$)", re.M)
    if key_pattern.search(block):
        block = key_pattern.sub(f"  {key}: {value}", block, count=1)
    else:
        block = block.rstrip() + f"\n  {key}: {value}\n"
    return src[:m.start(2)] + block + src[m.end(2):]

text = replace_in_section(text, "server", "host", "127.0.0.1")
text = replace_in_section(text, "server", "port", port)
text = replace_in_section(text, "server", "tls_enabled", "true" if https_enabled else "false")
text = replace_in_section(text, "server", "tls_auto_self_sign", "true" if https_enabled else "false")
text = replace_in_section(text, "log", "output", log_file)

tmp_path = None
try:
    with tempfile.NamedTemporaryFile(
        "w",
        encoding="utf-8",
        dir=str(path.parent),
        prefix=f".{path.name}.tmp.",
        delete=False,
    ) as handle:
        handle.write(text)
        handle.flush()
        os.fsync(handle.fileno())
        tmp_path = handle.name
    os.chmod(tmp_path, file_stat.st_mode & 0o777)
    if hasattr(os, "chown"):
        os.chown(tmp_path, file_stat.st_uid, file_stat.st_gid)
    os.replace(tmp_path, path)
except Exception:
    if tmp_path:
        Path(tmp_path).unlink(missing_ok=True)
    raise
PY
  success "$(t app.cyberstrikeai.success.config_adjusted "$PORT")"
}
setup_python_env() {
  step "$(t app.cyberstrikeai.step.python_env)"
  if ! cd "$INSTALL_DIR"; then
    error "$(t app.cyberstrikeai.error.install_dir_missing "$INSTALL_DIR")"
  fi
  if [[ ! -d "$VENV_DIR" ]]; then
    if ! python3 -m venv "$VENV_DIR"; then
      error "$(t app.cyberstrikeai.error.python_venv "$VENV_DIR")"
    fi
  fi
  if ! source "$VENV_DIR/bin/activate"; then
    error "$(t app.cyberstrikeai.error.python_activate "$VENV_DIR")"
  fi
  if ! python -m pip install --index-url "$PIP_INDEX_URL" --upgrade pip >/dev/null 2>&1; then
    warn "$(t app.cyberstrikeai.warn.pip_upgrade)"
  fi
  if [[ -f requirements.txt ]]; then
    local pip_log
    if ! pip_log=$(mktemp); then
      warn "$(t app.cyberstrikeai.warn.python_requirements)"
      return 0
    fi
    if python -m pip install --index-url "$PIP_INDEX_URL" -r requirements.txt >"$pip_log" 2>&1; then
      success "$(t app.cyberstrikeai.success.python_requirements)"
    else
      warn "$(t app.cyberstrikeai.warn.python_requirements)"
      tail -n 20 "$pip_log" | sed 's/^/  /' >&2 || true
    fi
    rm -f "$pip_log"
  else
    warn "$(t app.cyberstrikeai.warn.requirements_missing)"
  fi
}
build_binary() {
  step "$(t app.cyberstrikeai.step.build)"
  if ! cd "$INSTALL_DIR"; then
    error "$(t app.cyberstrikeai.error.install_dir_missing "$INSTALL_DIR")"
  fi
  export GOPROXY="$GOPROXY"
  if ! go mod download; then
    error "$(t app.cyberstrikeai.error.go_modules "$INSTALL_DIR")"
  fi
  local tmp_bin
  if ! tmp_bin=$(mktemp "${BIN_PATH}.tmp.XXXXXX"); then
    error "$(t app.cyberstrikeai.error.binary_build)"
  fi
  if ! go build -trimpath -ldflags="-s -w" -o "$tmp_bin" cmd/server/main.go; then
    rm -f "$tmp_bin"
    error "$(t app.cyberstrikeai.error.binary_build)"
  fi
  if [[ ! -s "$tmp_bin" ]]; then
    rm -f "$tmp_bin"
    error "$(t app.cyberstrikeai.error.binary_empty)"
  fi
  if ! chmod 0755 "$tmp_bin"; then
    rm -f "$tmp_bin"
    error "$(t app.cyberstrikeai.error.binary_build)"
  fi
  if ! mv "$tmp_bin" "$BIN_PATH"; then
    rm -f "$tmp_bin"
    error "$(t app.cyberstrikeai.error.binary_build)"
  fi
  success "$(t app.cyberstrikeai.success.binary_built "$BIN_PATH")"
}
restore_update_backup() {
  local bin_backup="$1" config_backup="$2"
  local bin_restore_tmp config_restore_tmp
  [[ -f "$bin_backup" ]] || return 1
  if ! bin_restore_tmp=$(mktemp "${BIN_PATH}.restore.XXXXXX"); then
    return 1
  fi
  if ! cp "$bin_backup" "$bin_restore_tmp" \
      || ! chmod 0755 "$bin_restore_tmp" \
      || ! chown "${SERVICE_USER}:${SERVICE_USER}" "$bin_restore_tmp" \
      || ! mv "$bin_restore_tmp" "$BIN_PATH"; then
    rm -f "$bin_restore_tmp"
    return 1
  fi
  if [[ -f "$config_backup" ]]; then
    if ! config_restore_tmp=$(mktemp "${CONFIG_FILE}.restore.XXXXXX"); then
      return 1
    fi
    if ! cp "$config_backup" "$config_restore_tmp" \
        || ! chown "${SERVICE_USER}:${SERVICE_USER}" "$config_restore_tmp" \
        || ! mv "$config_restore_tmp" "$CONFIG_FILE"; then
      rm -f "$config_restore_tmp"
      return 1
    fi
  fi
}
install_runtime_dirs() {
  step "$(t app.cyberstrikeai.step.runtime_dirs)"
  if ! mkdir -p "$LOG_DIR" "$INSTALL_DIR/data" "$INSTALL_DIR/tmp" "$BACKUP_DIR"; then
    error "$(t app.cyberstrikeai.error.runtime_dirs "$INSTALL_DIR" "$BACKUP_DIR")"
  fi
  require_safe_path "INSTALL_DIR" "$INSTALL_DIR"
  require_safe_path "BACKUP_DIR" "$BACKUP_DIR"
  if ! chown -R "${SERVICE_USER}:${SERVICE_USER}" "$INSTALL_DIR" "$BACKUP_DIR"; then
    error "$(t app.cyberstrikeai.error.runtime_dirs "$INSTALL_DIR" "$BACKUP_DIR")"
  fi
  if ! chmod 750 "$INSTALL_DIR" "$BACKUP_DIR"; then
    error "$(t app.cyberstrikeai.error.runtime_dirs "$INSTALL_DIR" "$BACKUP_DIR")"
  fi
  if ! chmod 750 "$LOG_DIR" "$INSTALL_DIR/data" "$INSTALL_DIR/tmp"; then
    error "$(t app.cyberstrikeai.error.runtime_dirs "$INSTALL_DIR" "$BACKUP_DIR")"
  fi
  success "$(t app.cyberstrikeai.success.runtime_dirs)"
}
write_systemd_unit() {
  step "$(t app.cyberstrikeai.step.systemd)"
  local https_env="false"
  _bool_true "$CSAI_HTTPS" && https_env="true"
  local unit_path="/etc/systemd/system/${SERVICE_NAME}.service"
  if ! systemd_write_unit "$unit_path" <<SERVICE
[Unit]
Description=CyberStrikeAI
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=${SERVICE_USER}
Group=${SERVICE_USER}
WorkingDirectory=${INSTALL_DIR}
Environment=CYBERSTRIKE_HTTPS=${https_env}
Environment=PATH=${VENV_DIR}/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
ExecStart=${BIN_PATH} -config ${CONFIG_FILE}
Restart=on-failure
RestartSec=5
TimeoutStopSec=30
KillSignal=SIGTERM
LimitNOFILE=65536
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=full
ReadWritePaths=${INSTALL_DIR} ${BACKUP_DIR}
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
SERVICE
  then
    error "$(t app.cyberstrikeai.error.systemd "$unit_path")"
  fi
  if ! systemctl daemon-reload; then
    error "$(t app.cyberstrikeai.error.systemd_reload "$SERVICE_NAME")"
  fi
  if ! systemctl enable "$SERVICE_NAME" --quiet; then
    warn "$(t app.cyberstrikeai.warn.service_enable_failed "$SERVICE_NAME" "$SERVICE_NAME")"
  fi
  success "$(t app.cyberstrikeai.success.systemd "$SERVICE_NAME")"
}
_write_nginx_site_link() {
  local target="$1" link_path="$2"
  if ! atomic_symlink "$target" "$link_path"; then
    error "$(t app.cyberstrikeai.error.nginx "$target")"
  fi
}
_write_nginx_config_file() {
  local nginx_conf="$1"
  if ! atomic_write_file "$nginx_conf" 644 root:root; then
    error "$(t app.cyberstrikeai.error.nginx "$nginx_conf")"
  fi
}
write_nginx_config() {
  _bool_true "$ENABLE_NGINX" || return 0
  step "$(t app.cyberstrikeai.step.nginx)"
  local server_name="_"
  [[ -n "$CSAI_DOMAIN" ]] && server_name="$CSAI_DOMAIN"
  local upstream_scheme="http"
  _bool_true "$CSAI_HTTPS" && upstream_scheme="https"
  if ! mkdir -p "$(dirname "$NGINX_CONF")" "$(dirname "$NGINX_LINK")"; then
    error "$(t app.cyberstrikeai.error.nginx_dirs "$NGINX_CONF")"
  fi
  _write_nginx_config_file "$NGINX_CONF" <<NGINX
server {
    listen ${PUBLIC_PORT};
    listen [::]:${PUBLIC_PORT};
    server_name ${server_name};

    client_max_body_size 256m;
    charset utf-8;

    location / {
        proxy_pass ${upstream_scheme}://127.0.0.1:${PORT};
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
        proxy_buffering off;
        proxy_ssl_verify off;
    }

    location /api/ {
        proxy_pass ${upstream_scheme}://127.0.0.1:${PORT};
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
        proxy_buffering off;
        proxy_ssl_verify off;
    }

    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;

    access_log /var/log/nginx/cyberstrike-ai_access.log;
    error_log  /var/log/nginx/cyberstrike-ai_error.log;
}
NGINX
  _write_nginx_site_link "$NGINX_CONF" "$NGINX_LINK" \
    || error "$(t app.cyberstrikeai.error.nginx "$NGINX_CONF")"
  if ! nginx -t; then
    error "$(t app.cyberstrikeai.error.nginx_test)"
  fi
  if ! systemctl enable nginx --quiet; then
    warn "$(t app.cyberstrikeai.warn.service_enable_failed "nginx" "nginx")"
  fi
  if systemctl is-active --quiet nginx; then
    if ! systemctl reload nginx; then
      if ! systemctl restart nginx; then
        error "$(t app.cyberstrikeai.error.nginx_start)"
      fi
    fi
  elif ! systemctl restart nginx; then
    error "$(t app.cyberstrikeai.error.nginx_start)"
  fi
  if ! wait_for_service nginx 10; then
    error "$(t app.cyberstrikeai.error.nginx_start)"
  fi
  success "$(t app.cyberstrikeai.success.nginx)"
}
open_firewall_ports() {
  _bool_true "$OPEN_FIREWALL" || return 0
  step "$(t app.cyberstrikeai.step.firewall)"
  local port_to_open="$PORT"
  local fw_error=false
  _bool_true "$ENABLE_NGINX" && port_to_open="$PUBLIC_PORT"
  if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q "Status: active"; then
    if ufw allow "${port_to_open}/tcp" >/dev/null 2>&1; then
      if _bool_true "$ENABLE_NGINX"; then
        success "$(t app.cyberstrikeai.success.ufw "$PUBLIC_PORT")"
      else
        success "$(t app.cyberstrikeai.success.ufw_backend "$PORT")"
      fi
      return 0
    fi
    fw_error=true
  fi
  if command -v iptables >/dev/null 2>&1; then
    if iptables -C INPUT -p tcp --dport "$port_to_open" -j ACCEPT 2>/dev/null \
        || iptables -A INPUT -p tcp --dport "$port_to_open" -j ACCEPT; then
      success "$(t app.cyberstrikeai.success.iptables "$port_to_open")"
      return 0
    fi
    fw_error=true
  fi
  if $fw_error; then
    warn "$(t app.cyberstrikeai.warn.firewall_config_failed "$port_to_open")"
  else
    warn "$(t app.cyberstrikeai.warn.no_firewall)"
  fi
}
write_logrotate() {
  local logrotate_tmp
  if ! logrotate_tmp=$(mktemp "${LOGROTATE_FILE}.XXXXXX"); then
    error "$(t app.cyberstrikeai.error.logrotate)"
  fi
  if ! cat > "$logrotate_tmp" <<ROTATE
${LOG_DIR}/*.log {
    daily
    rotate 14
    missingok
    notifempty
    copytruncate
    compress
}
ROTATE
  then
    rm -f "$logrotate_tmp"
    error "$(t app.cyberstrikeai.error.logrotate "$LOGROTATE_FILE")"
  fi
  if ! chmod 644 "$logrotate_tmp" \
      || ! chown root:root "$logrotate_tmp" \
      || ! mv "$logrotate_tmp" "$LOGROTATE_FILE"; then
    rm -f "$logrotate_tmp"
    error "$(t app.cyberstrikeai.error.logrotate "$LOGROTATE_FILE")"
  fi
}
write_backup_script() {
  local install_dir_literal config_file_literal backup_dir_literal keep_days_literal service_name_literal log_file_literal
  printf -v install_dir_literal '%q' "$INSTALL_DIR"
  printf -v config_file_literal '%q' "$CONFIG_FILE"
  printf -v backup_dir_literal '%q' "$BACKUP_DIR"
  printf -v keep_days_literal '%q' "$BACKUP_KEEP_DAYS"
  printf -v service_name_literal '%q' "$SERVICE_NAME"
  printf -v log_file_literal '%q' "${LOG_DIR}/backup.log"
  local msg_install_missing msg_backup_dir_failed msg_sqlite_integrity msg_backup_created msg_remove_failed
  msg_install_missing="$(t app.cyberstrikeai.backup.error.install_missing '%s')"
  msg_backup_dir_failed="$(t app.cyberstrikeai.backup.error.backup_dir_create '%s')"
  msg_sqlite_integrity="$(t app.cyberstrikeai.backup.warn.sqlite_integrity '%s' '%s')"
  msg_backup_created="$(t app.cyberstrikeai.backup.ok.created '%s')"
  msg_remove_failed="$(t app.cyberstrikeai.backup.warn.remove_failed '%s')"
  local backup_tmp
  if ! backup_tmp=$(mktemp "${BACKUP_SCRIPT}.XXXXXX"); then
    error "$(t app.cyberstrikeai.error.backup_script)"
  fi
  if ! cat > "$backup_tmp" <<BACKUP
#!/usr/bin/env bash
set -euo pipefail
umask 077

INSTALL_DIR=${install_dir_literal}
CONFIG_FILE=${config_file_literal}
BACKUP_DIR=${backup_dir_literal}
KEEP_DAYS=${keep_days_literal}
[[ "\$KEEP_DAYS" =~ ^[0-9]+$ ]] || KEEP_DAYS=0
SERVICE_NAME=${service_name_literal}
LOG_FILE=${log_file_literal}
MSG_INSTALL_MISSING="${msg_install_missing}"
MSG_BACKUP_DIR_FAILED="${msg_backup_dir_failed}"
MSG_SQLITE_INTEGRITY="${msg_sqlite_integrity}"
MSG_BACKUP_CREATED="${msg_backup_created}"
MSG_REMOVE_FAILED="${msg_remove_failed}"

_log() { echo "\$(date '+%F %T') \$*" >> "\$LOG_FILE"; }

if ! mkdir -p "\$BACKUP_DIR"; then
  printf "\$(date '+%F %T') [ERROR] %s\n" "\$(printf "\$MSG_BACKUP_DIR_FAILED" "\$BACKUP_DIR")" >&2
  exit 1
fi
if [[ ! -d "\$INSTALL_DIR" ]]; then
  _log "[ERROR] \$(printf "\$MSG_INSTALL_MISSING" "\$INSTALL_DIR")"
  printf "\$(date '+%F %T') [ERROR] %s\n" "\$(printf "\$MSG_INSTALL_MISSING" "\$INSTALL_DIR")" >&2
  exit 1
fi

if command -v sqlite3 >/dev/null 2>&1; then
  find "\$INSTALL_DIR/data" -maxdepth 1 -name "*.db" -type f 2>/dev/null | while read -r db; do
    sqlite3 "\$db" "PRAGMA wal_checkpoint(TRUNCATE);" >/dev/null 2>&1 || true
    integrity=\$(sqlite3 "\$db" "PRAGMA integrity_check;" 2>/dev/null || echo "error")
    if [[ "\$integrity" != "ok" ]]; then
      _log "[WARN] \$(printf "\$MSG_SQLITE_INTEGRITY" "\$db" "\$integrity")"
      printf "\$(date '+%F %T') [WARN] %s\n" "\$(printf "\$MSG_SQLITE_INTEGRITY" "\$db" "\$integrity")" >&2
    fi
  done
fi

ts=\$(date +%Y%m%d_%H%M%S)
archive="\$BACKUP_DIR/cyberstrike-ai_\${ts}.tar.gz"
tmp="\${archive}.tmp"

if tar -czf "\$tmp" \
  --exclude=".git" \
  --exclude="venv" \
  --exclude="cyberstrike-ai" \
  --exclude="*.tmp" \
  --exclude="logs/*.log" \
  -C "\$(dirname "\$INSTALL_DIR")" "\$(basename "\$INSTALL_DIR")"; then
  if ! mv "\$tmp" "\$archive"; then
    rm -f "\$tmp"
    exit 1
  fi
else
  rm -f "\$tmp"
  exit 1
fi

if [[ "\$KEEP_DAYS" -gt 0 ]]; then
  while IFS= read -r -d '' old_backup; do
    if ! rm -f "\$old_backup"; then
      _log "[WARN] \$(printf "\$MSG_REMOVE_FAILED" "\$old_backup")"
    fi
  done < <(find "\$BACKUP_DIR" -maxdepth 1 -name "cyberstrike-ai_*.tar.gz" -mtime "+\$KEEP_DAYS" -type f -print0 2>/dev/null)
fi

_log "[OK] \$(printf "\$MSG_BACKUP_CREATED" "\$archive")"
printf "\$(date '+%F %T') [OK] %s\n" "\$(printf "\$MSG_BACKUP_CREATED" "\$archive")"
BACKUP
  then
    rm -f "$backup_tmp"
    error "$(t app.cyberstrikeai.error.backup_script "$BACKUP_SCRIPT")"
  fi
  if ! chmod 750 "$backup_tmp" \
      || ! chown root:root "$backup_tmp" \
      || ! mv "$backup_tmp" "$BACKUP_SCRIPT"; then
    rm -f "$backup_tmp"
    error "$(t app.cyberstrikeai.error.backup_script "$BACKUP_SCRIPT")"
  fi
  local cron_tmp
  if ! cron_tmp=$(mktemp "${CRON_FILE}.XXXXXX"); then
    error "$(t app.cyberstrikeai.error.cron)"
  fi
  if ! cat > "$cron_tmp" <<CRON
SHELL=/bin/bash
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
30 3 * * * root ${BACKUP_SCRIPT} >> ${LOG_DIR}/backup.log 2>&1
CRON
  then
    rm -f "$cron_tmp"
    error "$(t app.cyberstrikeai.error.cron "$CRON_FILE")"
  fi
  if ! chmod 644 "$cron_tmp" \
      || ! chown root:root "$cron_tmp" \
      || ! mv "$cron_tmp" "$CRON_FILE"; then
    rm -f "$cron_tmp"
    error "$(t app.cyberstrikeai.error.cron "$CRON_FILE")"
  fi
}
start_service() {
  step "$(t app.cyberstrikeai.step.start)"
  app_check_port_conflict "$PORT"
  if systemctl restart "$SERVICE_NAME" && wait_for_service "$SERVICE_NAME" 35; then
    success "$(t app.cyberstrikeai.success.running "$SERVICE_NAME")"
  else
    journalctl -u "$SERVICE_NAME" -n 40 --no-pager >&2 || true
    error "$(t app.cyberstrikeai.error.start_failed "$SERVICE_NAME")"
  fi
}
health_check() {
  step "$(t app.cyberstrikeai.step.health)"
  local scheme="http"
  _bool_true "$CSAI_HTTPS" && scheme="https"
  local code backend_url public_url
  local health_pending=0
  backend_url="${scheme}://127.0.0.1:${PORT}/"
  code=$(curl -k -o /dev/null -s -w "%{http_code}" --max-time 8 "$backend_url" || echo "000")
  if [[ "$code" =~ ^(200|301|302|308)$ ]]; then
    success "$(t app.cyberstrikeai.success.backend_health "$backend_url" "$code")"
  else
    warn "$(t app.cyberstrikeai.warn.backend_health "$code")"
    health_pending=1
  fi
  if _bool_true "$ENABLE_NGINX"; then
    public_url="http://127.0.0.1:${PUBLIC_PORT}/"
    code=$(curl -H "Host: ${CSAI_DOMAIN:-localhost}" -o /dev/null -s -w "%{http_code}" --max-time 8 "$public_url" || echo "000")
    if [[ "$code" =~ ^(200|301|302|308)$ ]]; then
      success "$(t app.cyberstrikeai.success.nginx_health "$public_url" "$code")"
    else
      warn "$(t app.cyberstrikeai.warn.nginx_health "$code")"
      health_pending=1
    fi
  fi
  [[ "$health_pending" -eq 0 ]]
}
print_summary() {
  local summary_state="${1:-ready}"
  local ip
  ip=$(hostname -I 2>/dev/null | awk '{print $1}' || true)
  ip="${ip:-YOUR_SERVER_IP}"
  local backend_scheme="http"
  _bool_true "$CSAI_HTTPS" && backend_scheme="https"
  echo ""
  if [[ "$summary_state" == "pending" ]]; then
    echo -e "${BOLD}${GREEN}$(t app.cyberstrikeai.summary.title_pending)${NC}"
  else
    echo -e "${BOLD}${GREEN}$(t app.cyberstrikeai.summary.title_ready)${NC}"
  fi
  printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.service):" "$SERVICE_NAME"
  printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.install_dir):" "$INSTALL_DIR"
  printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.config):" "$CONFIG_FILE"
  printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.logs):" "$LOG_DIR"
  printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.backups):" "$BACKUP_DIR"
  printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.backend):" "${backend_scheme}://127.0.0.1:${PORT}/"
  if _bool_true "$ENABLE_NGINX"; then
    if [[ -n "$CSAI_DOMAIN" ]]; then
      printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.public):" "http://${CSAI_DOMAIN}:${PUBLIC_PORT}/"
    elif [[ -n "${ip:-}" ]]; then
      printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.public):" "http://${ip}:${PUBLIC_PORT}/"
    else
      printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.public):" "http://<server-ip>:${PUBLIC_PORT}/"
    fi
  fi
  echo ""
  echo "$(t app.cyberstrikeai.summary.commands)"
  echo "  systemctl status ${SERVICE_NAME} --no-pager"
  echo "  journalctl -u ${SERVICE_NAME} -n 80 --no-pager"
  echo "  bash $0 status"
  echo ""
  warn "$(t app.cyberstrikeai.warn.configure_model "$CONFIG_FILE")"
  warn "$(t app.cyberstrikeai.warn.authorized_only)"
}
do_install() {
  show_banner
  preflight_check "install"
  acquire_lock
  check_connectivity
  apt_install_base
  install_go_if_needed
  ensure_service_user
  clone_or_update_repo
  patch_config_port_and_paths
  setup_python_env
  build_binary
  install_runtime_dirs
  write_systemd_unit
  write_nginx_config
  write_logrotate
  write_backup_script
  open_firewall_ports
  app_save_config
  start_service
  local _install_summary_state="ready"
  if ! health_check; then
    _install_summary_state="pending"
  fi
  print_summary "$_install_summary_state"
  release_lock
}
do_backup() {
  show_banner
  preflight_check "backup"
  app_load_config _CSAI_DERIVE_PATHS
  acquire_lock
  step "$(t app.cyberstrikeai.step.manual_backup)"
  "$BACKUP_SCRIPT"
  info "$(t app.cyberstrikeai.info.latest_backups)"
  find "$BACKUP_DIR" -maxdepth 1 -name "cyberstrike-ai_*.tar.gz" -printf '%T@ %p\n' 2>/dev/null \
    | sort -rn | head -10 | awk '{print $2}' | while read -r file; do
        [[ -n "$file" ]] || continue
        printf '  %-70s %s\n' "$(basename "$file")" "$(du -sh "$file" 2>/dev/null | awk '{print $1}' || t status.unknown)" >&2
      done || true
  release_lock
}
do_update() {
  show_banner
  preflight_check "update"
  app_load_config _CSAI_DERIVE_PATHS
  acquire_lock
  check_connectivity
  [[ -d "$INSTALL_DIR/.git" ]] || error "$(t app.cyberstrikeai.error.not_git "$INSTALL_DIR")"
  step "$(t app.cyberstrikeai.step.preupdate_backup)"
  if [[ -x "$BACKUP_SCRIPT" ]]; then
    if ! "$BACKUP_SCRIPT"; then
      warn "$(t app.cyberstrikeai.warn.preupdate_backup)"
    fi
  fi
  local old_rev new_rev bin_bak config_bak service_was_active=false
  old_rev=$(git -C "$INSTALL_DIR" rev-parse --short HEAD 2>/dev/null || echo "unknown")
  systemctl is-active --quiet "$SERVICE_NAME" && service_was_active=true
  bin_bak="${BIN_PATH}.bak.$(date +%Y%m%d_%H%M%S)"
  config_bak="${CONFIG_FILE}.preupdate.$(date +%Y%m%d_%H%M%S)"
  write_backup_file "$BIN_PATH" "$bin_bak" \
    || error "$(t app.cyberstrikeai.error.backup_write "$bin_bak")"
  write_backup_file "$CONFIG_FILE" "$config_bak" \
    || error "$(t app.cyberstrikeai.error.backup_write "$config_bak")"
  step "$(t app.cyberstrikeai.step.update_source)"
  sync_repo_branch
  new_rev=$(git -C "$INSTALL_DIR" rev-parse --short HEAD 2>/dev/null || echo "unknown")
  setup_python_env
  patch_config_port_and_paths
  build_binary
  if ! chown -R "${SERVICE_USER}:${SERVICE_USER}" "$INSTALL_DIR"; then
    error "$(t app.cyberstrikeai.error.install_dir_owner "$INSTALL_DIR" "$SERVICE_USER")"
  fi
  if $service_was_active; then
    step "$(t app.cyberstrikeai.step.restart_updated)"
    if systemctl restart "$SERVICE_NAME" && wait_for_service "$SERVICE_NAME" 35; then
      success "$(t app.cyberstrikeai.success.update_complete "$old_rev" "$new_rev")"
      if ! health_check; then
        :
      fi
    else
      warn "$(t app.cyberstrikeai.warn.update_start_failed)"
      systemctl stop "$SERVICE_NAME" 2>/dev/null || true
      if restore_update_backup "$bin_bak" "$config_bak"; then
        if systemctl start "$SERVICE_NAME"; then
          if wait_for_service "$SERVICE_NAME" 35; then
            error "$(t app.cyberstrikeai.error.update_rollback_ok "$SERVICE_NAME")"
          else
            error "$(t app.cyberstrikeai.error.update_rollback_failed "$SERVICE_NAME")"
          fi
        else
          error "$(t app.cyberstrikeai.error.update_rollback_failed "$SERVICE_NAME")"
        fi
      else
        error "$(t app.cyberstrikeai.error.update_rollback_failed "$SERVICE_NAME")"
      fi
    fi
  else
    success "$(t app.cyberstrikeai.success.update_inactive "$old_rev" "$new_rev")"
  fi
  local _cleaned_old=0 _old_bak
  while IFS= read -r -d '' _old_bak; do
    if rm -f "$_old_bak"; then
      _cleaned_old=$(( _cleaned_old + 1 ))
    else
      warn "$(t app.cyberstrikeai.warn.cleanup_old_binary_failed "$_old_bak")"
    fi
  done < <(
    find "$INSTALL_DIR" -maxdepth 1 -name "${BIN_NAME}.bak.*" -type f -printf '%T@ %p\0' 2>/dev/null \
      | sort -z -rn | tail -z -n +4 | cut -z -d ' ' -f 2-
  )
  if [[ $_cleaned_old -gt 0 ]]; then
    info "$(t app.cyberstrikeai.info.cleaned_old_binaries "$_cleaned_old")"
  fi
  release_lock
}
do_status() {
  show_banner
  preflight_check "status"
  app_load_config _CSAI_DERIVE_PATHS
  step "$(t app.cyberstrikeai.step.service_status)"
  if systemctl is-active --quiet "$SERVICE_NAME" 2>/dev/null; then
    echo -e "  ${GREEN}[+]${NC} ${SERVICE_NAME}: $(t app.cyberstrikeai.status.running)"
  elif systemctl is-failed --quiet "$SERVICE_NAME" 2>/dev/null; then
    echo -e "  ${RED}[x]${NC} ${SERVICE_NAME}: $(t app.cyberstrikeai.status.failed)"
  else
    echo -e "  ${YELLOW}[!]${NC} ${SERVICE_NAME}: $(t app.cyberstrikeai.status.inactive)"
  fi
  systemctl status "$SERVICE_NAME" --no-pager -l 2>/dev/null | head -16 | sed 's/^/  /' >&2 || true
  step "$(t app.cyberstrikeai.step.version_paths)"
  if [[ -d "$INSTALL_DIR/.git" ]]; then
    printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.git_revision):" "$(git -C "$INSTALL_DIR" rev-parse --short HEAD 2>/dev/null || t status.unknown)"
    printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.git_branch):" "$(git -C "$INSTALL_DIR" rev-parse --abbrev-ref HEAD 2>/dev/null || t status.unknown)"
  fi
  if [[ -x "$BIN_PATH" ]]; then
    printf '  %-12s %s (%s)\n' "$(t app.cyberstrikeai.status.binary):" "$BIN_PATH" "$(du -sh "$BIN_PATH" 2>/dev/null | awk '{print $1}' || t status.unknown)"
  else
    printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.binary):" "$(t app.cyberstrikeai.status.missing)"
  fi
  printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.config):" "$CONFIG_FILE"
  printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.logs):" "$LOG_DIR"
  printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.backups):" "$BACKUP_DIR"
  step "$(t app.cyberstrikeai.step.resources)"
  local pid
  pid=$(systemctl show "$SERVICE_NAME" --property=MainPID --value 2>/dev/null || echo "0")
  if [[ "$pid" != "0" && -d "/proc/$pid" ]]; then
    echo "  PID:          $pid"
    printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.memory_rss):" "$(awk '/VmRSS/{printf "%.1f MB", $2/1024}' "/proc/$pid/status" 2>/dev/null || echo N/A)"
    printf '  %-12s %s%%\n' "$(t app.cyberstrikeai.status.cpu):" "$(ps -p "$pid" -o %cpu= 2>/dev/null | tr -d ' ')"
    printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.uptime):" "$(ps -p "$pid" -o etime= 2>/dev/null | tr -d ' ')"
  else
    printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.process):" "$(t app.cyberstrikeai.status.not_running)"
  fi
  step "$(t app.cyberstrikeai.step.health)"
  if ! health_check; then
    :
  fi
  step "$(t app.cyberstrikeai.step.nginx)"
  if _bool_true "$ENABLE_NGINX"; then
    if command -v nginx >/dev/null 2>&1; then
      systemctl is-active --quiet nginx \
        && printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.nginx):" "$(t app.cyberstrikeai.status.running)" \
        || printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.nginx):" "$(t app.cyberstrikeai.status.not_running)"
      [[ -f "$NGINX_CONF" ]] \
        && printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.config):" "$NGINX_CONF" \
        || printf '  %-12s %s\n' "$(t app.cyberstrikeai.summary.config):" "$(t app.cyberstrikeai.status.missing)"
      nginx -t >/dev/null 2>&1 \
        && printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.syntax):" "$(t app.cyberstrikeai.status.ok)" \
        || printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.syntax):" "$(t app.cyberstrikeai.status.failed)"
    else
      printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.nginx):" "$(t app.cyberstrikeai.status.not_installed)"
    fi
  else
    printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.nginx):" "$(t app.cyberstrikeai.status.disabled)"
  fi
  step "$(t app.cyberstrikeai.step.backups)"
  if [[ -d "$BACKUP_DIR" ]]; then
    local count size
    count=$(find "$BACKUP_DIR" -maxdepth 1 -name "cyberstrike-ai_*.tar.gz" 2>/dev/null | wc -l)
    size=$(du -sh "$BACKUP_DIR" 2>/dev/null | awk '{print $1}' || t status.unknown)
    printf '  %-12s %s (%s, %s)\n' "$(t app.cyberstrikeai.status.backup_dir):" "$BACKUP_DIR" "$size" "$(t app.cyberstrikeai.status.files "$count")"
    find "$BACKUP_DIR" -maxdepth 1 -name "cyberstrike-ai_*.tar.gz" -printf '%T@ %p\n' 2>/dev/null \
      | sort -rn | head -5 | awk '{print $2}' | while read -r file; do
          [[ -n "$file" ]] || continue
          printf '  %-70s %s\n' "$(basename "$file")" "$(du -sh "$file" 2>/dev/null | awk '{print $1}' || t status.unknown)" >&2
        done || true
  else
    printf '  %-12s %s\n' "$(t app.cyberstrikeai.status.backup_dir):" "$(t app.cyberstrikeai.status.missing)"
  fi
  echo ""
}
do_uninstall() {
  show_banner
  preflight_check "uninstall"
  app_load_config _CSAI_DERIVE_PATHS
  acquire_lock
  require_safe_path "INSTALL_DIR" "${INSTALL_DIR:-}"
  require_safe_path "BACKUP_DIR" "${BACKUP_DIR:-}"
  step "$(t app.cyberstrikeai.step.uninstall)"
  echo -e "${RED}${BOLD}"
  echo "$(t app.cyberstrikeai.uninstall.removes)"
  echo "  - $(t app.cyberstrikeai.uninstall.systemd "$SERVICE_NAME")"
  echo "  - $(t app.cyberstrikeai.uninstall.nginx "$NGINX_CONF")"
  echo "  - $(t app.cyberstrikeai.uninstall.logrotate_cron)"
  echo "  - $(t app.cyberstrikeai.uninstall.deploy_config "$CONF_FILE")"
  echo ""
  echo "$(t app.cyberstrikeai.uninstall.keep_default)"
  echo -e "${NC}"
  prompt "$(t app.cyberstrikeai.prompt.continue)"
  local confirm
  read -r confirm
  [[ "$confirm" == "YES" ]] || { info "$(t app.cyberstrikeai.info.cancelled)"; exit 0; }
  prompt "$(t app.cyberstrikeai.prompt.delete_install "$INSTALL_DIR")"
  local del_install
  read -r del_install
  prompt "$(t app.cyberstrikeai.prompt.delete_backup "$BACKUP_DIR")"
  local del_backup
  read -r del_backup
  systemctl stop "$SERVICE_NAME" 2>/dev/null || true
  systemctl disable "$SERVICE_NAME" 2>/dev/null || true
  rm -f "/etc/systemd/system/${SERVICE_NAME}.service"
  if ! systemctl daemon-reload; then
    error "$(t app.cyberstrikeai.error.systemd_reload "$SERVICE_NAME")"
  fi
  success "$(t app.cyberstrikeai.success.removed_systemd)"
  rm -f "$NGINX_LINK" "$NGINX_CONF"
  if command -v nginx >/dev/null 2>&1; then
    if nginx -t >/dev/null 2>&1; then
      systemctl reload nginx >/dev/null 2>&1 || nginx -t >&2 || true
    else
      nginx -t >&2 || true
    fi
  fi
  success "$(t app.cyberstrikeai.success.removed_nginx)"
  rm -f "$LOGROTATE_FILE" "$CRON_FILE" "$BACKUP_SCRIPT" "$CONF_FILE"
  success "$(t app.cyberstrikeai.success.removed_configs)"
  if [[ "${del_install,,}" == "y" ]]; then
    safe_rm_dir "$INSTALL_DIR" "INSTALL_DIR"
    success "$(t app.cyberstrikeai.success.deleted_install "$INSTALL_DIR")"
  else
    info "$(t app.cyberstrikeai.info.kept_install "$INSTALL_DIR")"
  fi
  if [[ "${del_backup,,}" == "y" ]]; then
    safe_rm_dir "$BACKUP_DIR" "BACKUP_DIR"
    success "$(t app.cyberstrikeai.success.deleted_backup "$BACKUP_DIR")"
  else
    info "$(t app.cyberstrikeai.info.kept_backup "$BACKUP_DIR")"
  fi
  if [[ "${del_install,,}" == "y" ]] && id "$SERVICE_USER" >/dev/null 2>&1; then
    if userdel "$SERVICE_USER" 2>/dev/null; then
      success "$(t app.cyberstrikeai.success.deleted_user "$SERVICE_USER")"
    else
      warn "$(t app.cyberstrikeai.warn.delete_user "$SERVICE_USER")"
    fi
  fi
  echo ""
  success "$(t app.cyberstrikeai.success.uninstalled)"
  release_lock
}
__DEPLOY_APP_IMPL_SCRIPT_END__

__DEPLOY_APP_IMPL_SCRIPT__ install_blog_impl.sh
#!/bin/bash
set -euo pipefail
BLOG_DOMAIN="blog.example.com"
BLOG_TITLE="${BLOG_TITLE:-$(t app.blog.site_title)}"
BLOG_AUTHOR="Abyte"
BLOG_DESCRIPTION="${BLOG_DESCRIPTION:-$(t app.blog.site_description)}"
BLOG_LANG="${BLOG_LANG:-$(t app.blog.site_lang)}"
SITE_DIR="/opt/blog/site"
PUBLIC_DIR="/opt/blog/public"
NGINX_ROOT="/var/www/blog"
THEME_NAME="hugo-theme-stack"
THEME_REPO="https://github.com/CaiJimmy/hugo-theme-stack.git"
ENABLE_CMS=true
CMS_BACKEND="github"
CMS_REPO="TheSkyC/my-hugo-blog"
CMS_BRANCH="main"
CMS_SITE_URL="https://${BLOG_DOMAIN}"
LOCK_FILE="/var/lock/blog-deploy.lock"

restore_nginx_root_backup() {
  [[ -e "$DEPLOY_BAK" || -L "$DEPLOY_BAK" ]] || return 0
  if ! safe_rm_dir "$NGINX_ROOT" "NGINX_ROOT"; then
    return 1
  fi
  if ! mv "$DEPLOY_BAK" "$NGINX_ROOT"; then
    return 1
  fi
}

_write_publish_script() {
  local publish_script="/usr/local/bin/blog-publish"
  local publish_tmp
  publish_tmp=$(mktemp "${publish_script}.XXXXXX") || error "$(t app.blog.error.publish_script)"
  if ! cat > "$publish_tmp" << BKSH
#!/bin/bash
set -euo pipefail
PUBLIC_DIR="${PUBLIC_DIR}"
NGINX_ROOT="${NGINX_ROOT}"
NGINX_ROOT_PARENT="\$(dirname "\$NGINX_ROOT")"
NGINX_ROOT_NAME="\$(basename "\$NGINX_ROOT")"
DEPLOY_TMP="\$(mktemp -d "\${NGINX_ROOT_PARENT}/.\${NGINX_ROOT_NAME}.new.XXXXXX")" || {
  echo "Failed to create a staging directory under \$NGINX_ROOT_PARENT" >&2
  exit 1
}
DEPLOY_BAK="\${NGINX_ROOT}.bak.\$(date +%Y%m%d%H%M%S)"
is_safe_path() {
  local path="\${1:-}"
  [[ -n "\$path" && "\$path" = /* ]] || return 1
  while [[ "\$path" != "/" && "\$path" == */ ]]; do path="\${path%/}"; done
  case "\$path" in
    /|.|..|*'/../'*|*'/..'|*'/./'*|*'/.')
      return 1
      ;;
    /bin|/boot|/dev|/etc|/home|/lib|/lib64|/opt|/proc|/root|/run|/sbin|/sys|/tmp|/usr|/var|/var/lib|/var/log|/usr/local|/usr/local/bin)
      return 1
      ;;
  esac
  return 0
}
safe_rm_dir() {
  local path="\$1"
  while [[ "\$path" != "/" && "\$path" == */ ]]; do path="\${path%/}"; done
  is_safe_path "\$path" || return 1
  [[ -e "\$path" || -L "\$path" ]] || return 0
  [[ -d "\$path" || -L "\$path" ]] || return 1
  rm -rf -- "\$path"
}
restore_nginx_root_backup() {
  [[ -e "\$DEPLOY_BAK" || -L "\$DEPLOY_BAK" ]] || return 0
  if ! safe_rm_dir "\$NGINX_ROOT" "NGINX_ROOT"; then
    return 1
  fi
  if ! mv "\$DEPLOY_BAK" "\$NGINX_ROOT"; then
    return 1
  fi
}
[[ -d "\$PUBLIC_DIR" ]] || { echo "PUBLIC_DIR is missing: \$PUBLIC_DIR" >&2; exit 1; }
if ! mkdir -p "\$NGINX_ROOT_PARENT"; then
  echo "Failed to create the Nginx root parent: \$NGINX_ROOT_PARENT" >&2
  exit 1
fi
if cp -a "\${PUBLIC_DIR}/." "\$DEPLOY_TMP/"; then
  if [[ -e "\$NGINX_ROOT" || -L "\$NGINX_ROOT" ]]; then
    if ! mv "\$NGINX_ROOT" "\$DEPLOY_BAK"; then
      rm -rf "\$DEPLOY_TMP"
      echo "Failed to back up the live Nginx root: \$NGINX_ROOT" >&2
      exit 1
    fi
  fi
  if mv "\$DEPLOY_TMP" "\$NGINX_ROOT"; then
    if [[ -e "\$DEPLOY_BAK" || -L "\$DEPLOY_BAK" ]]; then
      rm -rf "\$DEPLOY_BAK"
    fi
  else
    rm -rf "\$DEPLOY_TMP"
    restore_nginx_root_backup || {
      echo "Failed to restore the previous Nginx root: \$NGINX_ROOT" >&2
      exit 1
    }
    echo "Failed to replace the live Nginx root: \$NGINX_ROOT" >&2
    exit 1
  fi
else
  rm -rf "\$DEPLOY_TMP"
  echo "Failed to stage static output from \$PUBLIC_DIR" >&2
  exit 1
fi
BKSH
  then
    rm -f "$publish_tmp"
    error "$(t app.blog.error.publish_script)"
  fi
  if ! chmod 750 "$publish_tmp" \
      || ! chown root:root "$publish_tmp" \
      || ! mv "$publish_tmp" "$publish_script"; then
    rm -f "$publish_tmp"
    error "$(t app.blog.error.publish_script)"
  fi
  success "$(t app.blog.success.publish_script)"
}

backup_blog_file() {
  local source_path="$1" backup_path="$2"
  atomic_copy_file "$source_path" "$backup_path"
}

_write_nginx_site_link() {
  local target="$1" link_path="$2"
  if ! atomic_symlink "$target" "$link_path"; then
    error "$(t app.blog.error.nginx_write "$target")"
  fi
}
_write_nginx_config_file() {
  local nginx_conf="$1"
  if ! atomic_write_file "$nginx_conf" 644 root:root; then
    error "$(t app.blog.error.nginx_write "$nginx_conf")"
  fi
}

_write_blog_file() {
  local target_path="$1"
  if ! atomic_write_file "$target_path" 644; then
    error "$(t app.blog.error.file_write "$target_path")"
  fi
}

wait_for_service() {
  local service="$1"
  local timeout="${2:-10}"
  local elapsed=0
  while (( elapsed < timeout )); do
    if systemctl is-active --quiet "$service"; then
      return 0
    fi
    sleep 1
    elapsed=$(( elapsed + 1 ))
  done
  systemctl is-active --quiet "$service"
}

do_install() {
echo -e "\n${BOLD}${CYAN}"
cat << 'EOF'
  ██╗  ██╗██╗   ██╗ ██████╗  ██████╗     ██████╗ ██╗      ██████╗  ██████╗
  ██║  ██║██║   ██║██╔════╝ ██╔═══██╗    ██╔══██╗██║     ██╔═══██╗██╔════╝
  ███████║██║   ██║██║  ███╗██║   ██║    ██████╔╝██║     ██║   ██║██║  ███╗
  ██╔══██║██║   ██║██║   ██║██║   ██║    ██╔══██╗██║     ██║   ██║██║   ██║
  ██║  ██║╚██████╔╝╚██████╔╝╚██████╔╝    ██████╔╝███████╗╚██████╔╝╚██████╔╝
  ╚═╝  ╚═╝ ╚═════╝  ╚═════╝  ╚═════╝    ╚═════╝ ╚══════╝ ╚═════╝  ╚═════╝
EOF
echo -e "${NC}"
echo -e "  ${BOLD}$(t app.blog.banner_theme "${CYAN}hugo-theme-stack${NC}${BOLD}")${NC}"
echo -e "  ${BOLD}$(t app.blog.banner_stack)${NC}\n"
[[ $EUID -ne 0 ]] && error "$(t error.root_required "$0" "${1:-}")"
command -v apt-get >/dev/null 2>&1 || error "$(t app.blog.error.apt_only)"
command -v systemctl >/dev/null 2>&1 || error "$(t app.blog.error.systemd_required)"
ARCH=$(uname -m)
case $ARCH in
  x86_64)  DEB_ARCH="amd64" ;;
  aarch64) DEB_ARCH="arm64" ;;
  *)       error "$(t app.blog.error.arch "$ARCH")" ;;
esac
acquire_lock
step "$(t app.blog.step_install_deps)"
if ! apt-get update -qq; then
  error "$(t app.blog.error.apt_update)"
fi
if ! apt-get install -y -qq curl wget git nginx ca-certificates; then
  error "$(t app.blog.error.deps_install)"
fi
success "$(t app.blog.deps_installed)"
step "$(t app.blog.step_install_hugo)"
info "$(t app.blog.query_hugo)"
HUGO_VER=$(curl -fsSL --max-time 15 \
  "https://api.github.com/repos/gohugoio/hugo/releases/latest" \
  | grep '"tag_name"' | head -1 \
  | sed 's/.*"v\([^"]*\)".*/\1/') \
  || error "$(t app.blog.error.github_api)"
[[ -z "$HUGO_VER" ]] && error "$(t app.blog.error.hugo_version)"
success "$(t app.blog.latest_version "$HUGO_VER")"
DEB_URL="https://github.com/gohugoio/hugo/releases/download/v${HUGO_VER}/hugo_extended_${HUGO_VER}_linux-${DEB_ARCH}.deb"
info "$(t app.blog.download_url "$DEB_URL")"
if ! HUGO_DEB="$(mktemp /tmp/hugo.XXXXXX.deb)"; then
  error "$(t app.blog.error.hugo_download)"
fi
if ! wget -q --show-progress -O "$HUGO_DEB" "$DEB_URL"; then
  rm -f "$HUGO_DEB"
  error "$(t app.blog.error.hugo_download)"
fi
if [[ ! -s "$HUGO_DEB" ]]; then
  rm -f "$HUGO_DEB"
  error "$(t app.blog.error.hugo_download)"
fi
if ! dpkg -i "$HUGO_DEB"; then
  rm -f "$HUGO_DEB"
  error "$(t app.blog.error.hugo_install)"
fi
rm -f "$HUGO_DEB"
success "$(t app.blog.hugo_installed "$(hugo version | head -1)")"
step "$(t app.blog.step_init_site)"
if ! mkdir -p "$(dirname "$SITE_DIR")"; then
  error "$(t app.blog.error.site_parent_dir "$SITE_DIR")"
fi
if [[ -d "$SITE_DIR" ]]; then
  warn "$(t app.blog.site_exists "$SITE_DIR")"
else
  if ! hugo new site "$SITE_DIR" --format toml; then
    error "$(t app.blog.error.site_create "$SITE_DIR" "$SITE_DIR")"
  fi
  success "$(t app.blog.site_created "$SITE_DIR")"
fi
if [[ ! -d "${SITE_DIR}/.git" ]]; then
  if ! git -C "$SITE_DIR" init -q; then
    error "$(t app.blog.error.git_init "$SITE_DIR" "$SITE_DIR")"
  fi
  if ! git -C "$SITE_DIR" config user.email "blog@localhost" \
      || ! git -C "$SITE_DIR" config user.name "${BLOG_AUTHOR}"; then
    error "$(t app.blog.error.git_config "$SITE_DIR")"
  fi
  success "$(t app.blog.git_initialized)"
fi
step "$(t app.blog.step_theme)"
THEME_DIR="${SITE_DIR}/themes/${THEME_NAME}"
if [[ -d "$THEME_DIR" && -f "$THEME_DIR/theme.toml" ]]; then
  info "$(t app.blog.theme_exists)"
  success "$(t app.blog.theme_current)"
else
  info "$(t app.blog.clone_theme)"
  if ! git -C "$SITE_DIR" submodule add --depth 1 "$THEME_REPO" "themes/${THEME_NAME}" 2>/dev/null; then
    if ! git clone --depth 1 "$THEME_REPO" "$THEME_DIR"; then
      error "$(t app.blog.error.theme_install "$THEME_DIR")"
    fi
    rm -rf "$THEME_DIR/.git"
  fi
  success "$(t app.blog.theme_installed)"
fi
step "$(t app.blog.step_config)"
CONFIG_FILE="${SITE_DIR}/hugo.toml"
if [[ -f "$CONFIG_FILE" && $(wc -l < "$CONFIG_FILE") -gt 3 ]]; then
  backup_blog_file "$CONFIG_FILE" "${CONFIG_FILE}.bak.$(date +%Y%m%d%H%M%S)" \
    || error "$(t app.blog.error.file_write "$CONFIG_FILE")"
  warn "$(t app.blog.config_backed_up)"
fi
if [[ -n "$BLOG_DOMAIN" ]]; then
  BASE_URL="https://${BLOG_DOMAIN}"
else
  BASE_URL="http://localhost"
fi
_write_blog_file "$CONFIG_FILE" << TOML
baseURL = "${BASE_URL}"
locale = "${BLOG_LANG}"
defaultContentLanguage = "${BLOG_LANG}"
title = "${BLOG_TITLE}"
theme = "${THEME_NAME}"

# Pagination.
paginate = 10

# Enable Git metadata for last-modified timestamps.
enableGitInfo = true

[params]
  mainSections = ["post"]
  description = "${BLOG_DESCRIPTION}"

  [params.sidebar]
    emoji = "✍️"
    subtitle = "${BLOG_DESCRIPTION}"

    # Uncomment this block after placing an avatar at assets/img/avatar.png.
    # [params.sidebar.avatar]
    #   enabled = true
    #   local   = true
    #   src     = "img/avatar.png"

  [params.footer]
    since = $(date +%Y)
    customText = ""

  [params.article]
    math = false
    toc = true
    readingTime = true
    license.enabled = false

  [params.comments]
    enabled = false

[author]
  name = "${BLOG_AUTHOR}"

[menu]
  [[menu.main]]
    name = "$(t app.blog.menu_home)"
    url = "/"
    weight = 1
  [[menu.main]]
    name = "$(t app.blog.menu_archives)"
    url = "/archives"
    weight = 2
  [[menu.main]]
    name = "$(t app.blog.menu_categories)"
    url = "/categories"
    weight = 3
  [[menu.main]]
    name = "$(t app.blog.menu_tags)"
    url = "/tags"
    weight = 4
  [[menu.main]]
    name = "$(t app.blog.menu_about)"
    url = "/about"
    weight = 5

[taxonomies]
  category = "categories"
  tag = "tags"
  series = "series"
TOML
success "$(t app.blog.config_written "$CONFIG_FILE")"
step "$(t app.blog.step_content)"
if ! mkdir -p \
  "${SITE_DIR}/content/post/hello-world" \
  "${SITE_DIR}/content/page/about" \
  "${SITE_DIR}/content/page/archives" \
  "${SITE_DIR}/static/img"; then
  error "$(t app.blog.error.content_dirs "$SITE_DIR")"
fi
if [[ ! -f "${SITE_DIR}/content/post/hello-world/index.md" ]]; then
_write_blog_file "${SITE_DIR}/content/post/hello-world/index.md" << MD
+++
title = "$(t app.blog.post_title)"
date = "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
description = "$(t app.blog.post_description)"
draft = false
categories = ["$(t app.blog.post_category)"]
tags = ["Hugo", "$(t app.blog.post_tag_blog)"]
+++

## $(t app.blog.post_heading)

$(t app.blog.post_intro)

### $(t app.blog.post_why_heading)

- $(t app.blog.post_fast_build)
- $(t app.blog.post_markdown)
- $(t app.blog.post_theme)
- $(t app.blog.post_open_source)

### $(t app.blog.post_start_heading)

$(t app.blog.post_start_body)

\`\`\`bash
# Create a new post quickly.
hugo new content post/my-new-post/index.md
\`\`\`

$(t app.blog.post_closing)
MD
success "$(t app.blog.sample_post_created)"
fi
if [[ ! -f "${SITE_DIR}/content/page/about/index.md" ]]; then
_write_blog_file "${SITE_DIR}/content/page/about/index.md" << MD
+++
title = "$(t app.blog.about_title)"
date = "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
menu = "main"
+++

## $(t app.blog.about_heading)

$(t app.blog.about_intro "$BLOG_AUTHOR")

$(t app.blog.about_body)

---

*$(t app.blog.about_footer)*
MD
success "$(t app.blog.about_created)"
fi
if [[ ! -f "${SITE_DIR}/content/page/archives/index.md" ]]; then
_write_blog_file "${SITE_DIR}/content/page/archives/index.md" << MD
+++
title = "$(t app.blog.archives_title)"
date = "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
layout = "archives"
+++
MD
success "$(t app.blog.archives_created)"
fi
step "$(t app.blog.step_cms)"
if [[ "$ENABLE_CMS" != "true" ]]; then
  warn "$(t app.blog.cms_skipped)"
else
  CMS_ADMIN_DIR="${SITE_DIR}/static/admin"
  if ! mkdir -p "$CMS_ADMIN_DIR"; then
    error "$(t app.blog.error.cms_admin_dir "$CMS_ADMIN_DIR")"
  fi
  _write_blog_file "${CMS_ADMIN_DIR}/index.html" << HTML
<!doctype html>
<html>
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <meta name="robots" content="noindex" />
    <title>$(t app.blog.cms_title)</title>
  </head>
  <body>
    <script src="https://unpkg.com/decap-cms@^3.0.0/dist/decap-cms.js"></script>
  </body>
</html>
HTML
  _write_blog_file "${CMS_ADMIN_DIR}/config.yml" << YAML
# ─────────────────────────────────────────────
#  Decap CMS configuration for hugo-theme-stack.
#  Docs: https://decapcms.org/docs/configuration-options/
# ─────────────────────────────────────────────

backend:
  name: ${CMS_BACKEND}
  repo: ${CMS_REPO}
  branch: ${CMS_BRANCH}
  # Uncomment and fill this when using a self-hosted OAuth proxy.
  # base_url: https://your-oauth-server.com

site_url: ${CMS_SITE_URL}

# Media paths are relative to the Hugo project root.
media_folder: "static/img/uploads"
public_folder: "/img/uploads"

collections:

  # ── Blog posts (content/post/) ──────────────────────────────
  - name: "post"
    label: "$(t app.blog.cms_posts)"
    label_singular: "$(t app.blog.cms_post)"
    folder: "content/post"
    path: "{{slug}}/index"
    media_folder: ""
    public_folder: ""
    create: true
    slug: "{{slug}}"
    preview_path: "post/{{slug}}/"
    format: toml-frontmatter
    fields:
      - { label: "$(t app.blog.cms_title_field)", name: "title", widget: "string" }
      - { label: "$(t app.blog.cms_date_field)", name: "date", widget: "datetime", date_format: "YYYY-MM-DD", time_format: "HH:mm:ss", format: "YYYY-MM-DDTHH:mm:ssZ" }
      - { label: "$(t app.blog.cms_description_field)", name: "description", widget: "string", required: false }
      - { label: "$(t app.blog.cms_draft_field)", name: "draft", widget: "boolean", default: false }
      - label: "$(t app.blog.cms_categories_field)"
        name: "categories"
        widget: "list"
        allow_add: true
        default: []
        field: { label: "$(t app.blog.cms_category_field)", name: "category", widget: "string" }
      - label: "$(t app.blog.cms_tags_field)"
        name: "tags"
        widget: "list"
        allow_add: true
        default: []
        field: { label: "$(t app.blog.cms_tag_field)", name: "tag", widget: "string" }
      - label: "$(t app.blog.cms_series_field)"
        name: "series"
        widget: "list"
        allow_add: true
        required: false
        field: { label: "$(t app.blog.cms_series_item_field)", name: "series", widget: "string" }
      - label: "$(t app.blog.cms_image_field)"
        name: "image"
        widget: "image"
        required: false
        choose_url: false
        hint: "$(t app.blog.cms_image_hint)"
      - { label: "$(t app.blog.cms_weight_field)", name: "weight", widget: "number", required: false, value_type: "int" }
      - { label: "$(t app.blog.cms_body_field)", name: "body", widget: "markdown" }

  # ── Standalone pages (content/page/) ────────────────────────
  - name: "page"
    label: "$(t app.blog.cms_pages)"
    label_singular: "$(t app.blog.cms_page)"
    folder: "content/page"
    path: "{{slug}}/index"
    create: true
    format: toml-frontmatter
    fields:
      - { label: "$(t app.blog.cms_title_field)", name: "title", widget: "string" }
      - { label: "$(t app.blog.cms_date_field)", name: "date", widget: "datetime", format: "YYYY-MM-DDTHH:mm:ssZ" }
      - { label: "$(t app.blog.cms_draft_field)", name: "draft", widget: "boolean", default: false }
      - label: "$(t app.blog.cms_menu_field)"
        name: "menu"
        widget: "select"
        required: false
        options: ["main"]
        hint: "$(t app.blog.cms_menu_hint)"
      - { label: "$(t app.blog.cms_layout_field)", name: "layout", widget: "string", required: false, hint: "$(t app.blog.cms_layout_hint)" }
      - { label: "$(t app.blog.cms_body_field)", name: "body", widget: "markdown" }
YAML
  success "$(t app.blog.cms_config_created "${CMS_ADMIN_DIR}/")"
  info "$(t app.blog.cms_admin_url "$CMS_SITE_URL")"
fi
step "$(t app.blog.step_build)"
if ! mkdir -p "$PUBLIC_DIR"; then
  error "$(t app.blog.error.public_dir "$PUBLIC_DIR")"
fi
if ! cd "$SITE_DIR"; then
  error "$(t app.blog.error.site_access "$SITE_DIR")"
fi
if ! git add -A; then
  error "$(t app.blog.error.git_stage "$SITE_DIR")"
fi
if git diff --cached --quiet; then
  :
else
  _git_diff_status=$?
  if [[ "$_git_diff_status" -eq 1 ]]; then
    if ! git commit -q -m "init: add site content"; then
      error "$(t app.blog.error.git_commit "$SITE_DIR")"
    fi
  else
    error "$(t app.blog.error.git_diff "$SITE_DIR")"
  fi
fi
info "$(t app.blog.git_committed)"
hugo --destination "$PUBLIC_DIR" --gc --minify \
  || error "$(t app.blog.error.hugo_build)"
PAGE_COUNT=$(find "$PUBLIC_DIR" -name "*.html" | wc -l)
success "$(t app.blog.build_complete "$PAGE_COUNT")"
step "$(t app.blog.step_nginx)"
NGINX_ROOT_PARENT="$(dirname "$NGINX_ROOT")"
NGINX_ROOT_NAME="$(basename "$NGINX_ROOT")"
if ! mkdir -p "$NGINX_ROOT_PARENT"; then
  error "$(t app.blog.error.nginx_root_parent "$NGINX_ROOT_PARENT")"
fi
if ! DEPLOY_TMP="$(mktemp -d "${NGINX_ROOT_PARENT}/.${NGINX_ROOT_NAME}.new.XXXXXX")"; then
  error "$(t app.blog.error.static_deploy "$NGINX_ROOT")"
fi
DEPLOY_BAK="${NGINX_ROOT}.bak.$(date +%Y%m%d%H%M%S)"
if cp -a "${PUBLIC_DIR}/." "$DEPLOY_TMP/"; then
  if [[ -e "$NGINX_ROOT" || -L "$NGINX_ROOT" ]]; then
    if ! mv "$NGINX_ROOT" "$DEPLOY_BAK"; then
      rm -rf "$DEPLOY_TMP"
      error "$(t app.blog.error.static_deploy "$NGINX_ROOT")"
    fi
  fi
  if mv "$DEPLOY_TMP" "$NGINX_ROOT"; then
    if [[ -e "$DEPLOY_BAK" || -L "$DEPLOY_BAK" ]]; then
      rm -rf "$DEPLOY_BAK"
    fi
  else
    rm -rf "$DEPLOY_TMP"
    restore_nginx_root_backup || error "$(t app.blog.error.static_deploy "$NGINX_ROOT")"
    error "$(t app.blog.error.static_deploy "$NGINX_ROOT")"
  fi
else
  rm -rf "$DEPLOY_TMP"
  error "$(t app.blog.error.static_deploy "$NGINX_ROOT")"
fi
success "$(t app.blog.static_deployed "$NGINX_ROOT")"
_write_publish_script
NGINX_CONF="/etc/nginx/sites-available/blog"
_write_nginx_config_file "$NGINX_CONF" << NGINX
server {
    listen 80;
    listen [::]:80;

    server_name ${BLOG_DOMAIN:-_};   # Match all hosts when no domain is configured.
    root ${NGINX_ROOT};
    index index.html;

    # Character encoding.
    charset utf-8;

    # Static asset caching.
    location ~* \.(css|js|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)$ {
        expires 30d;
        add_header Cache-Control "public, no-transform";
    }

    # Hugo-generated RSS.
    location /index.xml {
        add_header Content-Type "application/rss+xml; charset=utf-8";
    }

    # Decap CMS admin SPA entrypoint; disable caching and indexing.
    location /admin/ {
        try_files \$uri \$uri/ /admin/index.html;
        add_header Cache-Control "no-store, no-cache, must-revalidate";
        add_header X-Robots-Tag "noindex, nofollow";
    }

    # Keep Decap CMS config.yml uncached for live configuration updates.
    location = /admin/config.yml {
        add_header Cache-Control "no-store";
    }

    # 404 handling.
    error_page 404 /404.html;
    location = /404.html {
        internal;
    }

    # Gzip compression.
    gzip on;
    gzip_types text/plain text/css application/json application/javascript
               text/xml application/xml application/xml+rss text/javascript
               application/x-yaml;
    gzip_min_length 1024;

    # Security headers.
    add_header X-Frame-Options "SAMEORIGIN";
    add_header X-Content-Type-Options "nosniff";
    add_header Referrer-Policy "strict-origin-when-cross-origin";

    # Logs.
    access_log /var/log/nginx/blog_access.log;
    error_log  /var/log/nginx/blog_error.log;
}
NGINX
_write_nginx_site_link "$NGINX_CONF" /etc/nginx/sites-enabled/blog \
  || error "$(t app.blog.error.nginx_write "$NGINX_CONF")"
rm -f /etc/nginx/sites-enabled/default
nginx -t || error "$(t app.blog.error.nginx_config)"
success "$(t app.blog.nginx_configured)"
step "$(t app.blog.step_firewall)"
FW_DONE=false
FW_ERROR=false
if command -v ufw &>/dev/null && ufw status 2>/dev/null | grep -q "Status: active"; then
  if ufw allow "Nginx Full" > /dev/null 2>&1 \
      || { ufw allow 80/tcp > /dev/null 2>&1 && ufw allow 443/tcp > /dev/null 2>&1; }; then
    success "$(t app.blog.ufw_opened)"
    FW_DONE=true
  else
    FW_ERROR=true
  fi
fi
if ! $FW_DONE && command -v iptables &>/dev/null; then
  iptables_ok=true
  for PORT in 80 443; do
    if ! iptables -C INPUT -p tcp --dport "$PORT" -j ACCEPT 2>/dev/null; then
      if ! iptables -A INPUT -p tcp --dport "$PORT" -j ACCEPT; then
        iptables_ok=false
        break
      fi
    fi
  done
  if $iptables_ok; then
    success "$(t app.blog.iptables_opened)"
    FW_DONE=true
  else
    FW_ERROR=true
  fi
fi
if ! $FW_DONE; then
  if $FW_ERROR; then
    warn "$(t app.blog.firewall_config_failed)"
  else
    warn "$(t app.blog.firewall_missing)"
  fi
fi
step "$(t app.blog.step_start_nginx)"
if ! systemctl enable nginx --quiet; then
  warn "$(t app.blog.warn.service_enable_failed "nginx" "nginx")"
fi
if systemctl restart nginx && wait_for_service nginx 10; then
  success "$(t app.blog.nginx_started)"
else
  error "$(t app.blog.error.nginx_start)"
fi
step "$(t app.blog.step_health)"
local _blog_summary_state="ready"
HTTP_CODE=$(curl -H "Host: ${BLOG_DOMAIN:-localhost}" -o /dev/null -s -w "%{http_code}" --max-time 5 "http://127.0.0.1/" || echo "000")
if [[ "$HTTP_CODE" == "200" ]]; then
  success "$(t app.blog.http_ok)"
else
  warn "$(t app.blog.http_warn "$HTTP_CODE")"
  _blog_summary_state="pending"
fi
INTERNAL_IP=$(hostname -I 2>/dev/null | awk '{print $1}' || true)
INTERNAL_IP="${INTERNAL_IP:-YOUR_SERVER_IP}"
echo ""
echo -e "${BOLD}${GREEN}"
echo "  ╔══════════════════════════════════════════════════════╗"
if [[ "$_blog_summary_state" == "pending" ]]; then
  printf "  ║               %s                     ║\n" "$(t app.blog.summary_title_pending)"
else
  printf "  ║               %s                     ║\n" "$(t app.blog.summary_title_ready)"
fi
echo "  ╠══════════════════════════════════════════════════════╣"
if [[ -n "$BLOG_DOMAIN" ]]; then
echo -e "  ║  $(t app.blog.public_url)  ${CYAN}http://${BLOG_DOMAIN}${GREEN}"
fi
echo -e "  ║  $(t app.blog.internal_url)  ${CYAN}http://${INTERNAL_IP}${GREEN}"
if [[ "$ENABLE_CMS" == "true" ]]; then
echo -e "  ║  $(t app.blog.cms_admin)  ${CYAN}http://${INTERNAL_IP}/admin/${GREEN}  ($(t app.blog.oauth_required))"
fi
echo "  ╠══════════════════════════════════════════════════════╣"
echo -e "  ║  $(t app.blog.site_dir)  ${YELLOW}${SITE_DIR}${GREEN}"
echo -e "  ║  $(t app.blog.posts_dir)  ${YELLOW}${SITE_DIR}/content/post/${GREEN}"
echo -e "  ║  $(t app.blog.public_dir)  ${YELLOW}${NGINX_ROOT}${GREEN}"
if [[ "$ENABLE_CMS" == "true" ]]; then
echo -e "  ║  $(t app.blog.cms_config)  ${YELLOW}${SITE_DIR}/static/admin/config.yml${GREEN}"
fi
echo "  ╚══════════════════════════════════════════════════════╝"
echo -e "${NC}"
echo -e "  ${BOLD}$(t app.blog.workflow_title)${NC}"
echo ""
echo -e "  ${CYAN}# $(t app.blog.workflow_new_post)${NC}"
echo -e "  cd ${SITE_DIR}"
echo -e "  hugo new content post/my-post/index.md"
echo ""
echo -e "  ${CYAN}# $(t app.blog.workflow_preview)${NC}"
echo -e "  hugo server -D --bind 0.0.0.0 --port 1313"
echo -e "  # $(t app.blog.workflow_visit "$INTERNAL_IP")"
echo ""
echo -e "  ${CYAN}# $(t app.blog.workflow_publish)${NC}"
echo -e "  hugo --destination ${PUBLIC_DIR} --gc --minify"
echo -e "  /usr/local/bin/blog-publish"
echo ""
if [[ "$ENABLE_CMS" == "true" ]]; then
echo -e "  ${BOLD}$(t app.blog.cms_usage)${NC}"
echo ""
echo -e "  ${CYAN}# $(t app.blog.cms_github_backend)${NC}"
echo -e "  $(t app.blog.cms_oauth_step1)"
echo -e "$(t app.blog.cms_oauth_homepage "$CMS_SITE_URL")"
echo -e "$(t app.blog.cms_oauth_callback)"
echo -e "$(t app.blog.cms_oauth_proxy)"
echo -e "  $(t app.blog.cms_push_repo "$SITE_DIR" "$CMS_REPO")"
echo -e "  $(t app.blog.cms_login "$CMS_SITE_URL")"
echo ""
echo -e "  ${CYAN}# $(t app.blog.cms_local_debug)${NC}"
echo -e "  # $(t app.blog.cms_test_repo "$SITE_DIR")"
echo -e "  # $(t app.blog.cms_run_server)"
echo ""
fi
echo -e "  ${BOLD}$(t app.blog.https_title)${NC}"
echo -e "  apt install certbot python3-certbot-nginx -y"
echo -e "  certbot --nginx -d ${BLOG_DOMAIN:-your-domain.com}"
echo ""
echo -e "  ${BOLD}$(t app.blog.theme_docs)${NC}  https://stack.jimmycai.com"
echo -e "  ${BOLD}📖  Decap CMS：${NC} https://decapcms.org/docs/"
echo ""
echo -e "  ${YELLOW}${BOLD}[i]${NC} $(t app.blog.rebuild_hint "$PUBLIC_DIR")"
echo ""
}
